// ==UserScript==
// @name         MCStories Archive Browser
// @namespace    https://github.com/your-name/mcstories-browser
// @version      1.5.0
// @description  Adds a searchable, filterable browser (tags, authors, word counts, bookmarks) over the MCStories archive, plus switchable reading themes.
// @match        *://mcstories.com/*
// @match        *://www.mcstories.com/*
// @grant        GM_xmlhttpRequest
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_registerMenuCommand
// @connect      raw.githubusercontent.com
// @updateURL    https://raw.githubusercontent.com/arbiter546/MCStories-Redux/main/mcstories-browser.user.js
// @downloadURL  https://raw.githubusercontent.com/arbiter546/MCStories-Redux/main/mcstories-browser.user.js
// @run-at       document-start
// ==/UserScript==

(function () {
  'use strict';
  if (window.top !== window.self) return;

  // ---- Settings -----------------------------------------------------------
  // Where the story metadata (authors, tags, synopses, word counts) lives.
  // Fetched once and cached; no story text is ever downloaded or stored.
  var DATA_URL = "https://raw.githubusercontent.com/arbiter546/MCStories-Redux/main/stories.json";
  var CACHE_TTL_MS = 6 * 60 * 60 * 1000; // re-check every 6 hours
  var CACHE_KEY = 'mco.data.v1';

  var APP_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n<title>Browse Stories — The Erotic Mind-Control Story Archive</title>\n<meta name=\"description\" content=\"Every story in the archive, one page, filterable by category and sortable by title, date, or length.\"/>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,600;1,9..144,500&family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;1,8..60,400&family=IBM+Plex+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --ink:#15120e;\n    --ink-2:#1d1912;\n    --ink-3:#242018;\n    --ink-4:#2f2a20;\n    --parchment:#ede3cf;\n    --parchment-dim:#c9bfa8;\n    --brass:#a8823e;\n    --brass-bright:#d9b46a;\n    --muted:#9c948a;\n    --focus:#d9b46a;\n    --line:#3a3327;\n  }\n\n  *{ box-sizing:border-box; }\n  html{ background:var(--ink); color-scheme:dark; }\n\n  /* Replace Chrome's default light scrollbars with slim themed ones. */\n  *{ scrollbar-width:thin; scrollbar-color:var(--line) transparent; }\n  ::-webkit-scrollbar{ width:10px; height:10px; }\n  ::-webkit-scrollbar-track{ background:transparent; }\n  ::-webkit-scrollbar-thumb{\n    background:var(--line);\n    border-radius:6px;\n    border:2px solid var(--ink);\n  }\n  ::-webkit-scrollbar-thumb:hover{ background:var(--brass); }\n  .author-panel::-webkit-scrollbar-thumb{ border-color:var(--ink-2); }\n\n  body{\n    margin:0;\n    background:\n      radial-gradient(1200px 600px at 15% -10%, #241d13 0%, transparent 60%),\n      var(--ink);\n    color:var(--parchment);\n    font-family:'Source Serif 4', Georgia, serif;\n    line-height:1.5;\n  }\n\n  a{ color:inherit; }\n  a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, .row:focus-visible, summary:focus-visible, .author-story-item:focus-visible{\n    outline:2px solid var(--focus);\n    outline-offset:2px;\n    border-radius:2px;\n  }\n\n  .wrap{\n    max-width:1280px;\n    margin:0 auto;\n    padding:3rem 1.5rem 4rem;\n    transition:margin-left .3s ease;\n  }\n\n  header{ margin-bottom:1.5rem; }\n\n  .eyebrow{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    letter-spacing:.2em;\n    text-transform:uppercase;\n    color:var(--brass);\n    margin:0 0 .6rem;\n  }\n\n  header a.back{ text-decoration:none; color:var(--muted); }\n  header a.back:hover{ color:var(--parchment); }\n\n  h1{\n    font-family:'Fraunces', serif;\n    font-weight:600;\n    font-size:clamp(1.7rem, 4vw, 2.4rem);\n    line-height:1.1;\n    margin:.3rem 0 .5rem;\n    letter-spacing:-.01em;\n  }\n\n  .subhead{ color:var(--parchment-dim); font-size:.95rem; margin:0; }\n\n  /* --- Two-column page layout --- */\n  .page{\n    display:flex;\n    gap:2rem;\n    align-items:flex-start;\n  }\n\n  .main-col{\n    flex:1;\n    min-width:0;\n  }\n\n  .sidebar{\n    width:300px;\n    flex-shrink:0;\n    position:sticky;\n    top:0;\n    max-height:100vh;\n    overflow-y:auto;\n    padding:1.25rem 0 2rem 1.25rem;\n    border-left:1px solid var(--line);\n  }\n\n  @media (max-width:900px){\n    .page{ flex-direction:column; }\n    .sidebar{\n      width:100%;\n      position:static;\n      max-height:none;\n      overflow-y:visible;\n      border-left:none;\n      border-top:1px solid var(--line);\n      padding:1.25rem 0 0;\n      margin-top:1.5rem;\n    }\n  }\n\n  /* --- Author mini-portfolio panel ---\n     Slides in from the left and pushes .wrap to the right (eating into\n     what was the centered page's right-hand whitespace) rather than\n     overlaying the page, so search/filters stay visible and usable. */\n  .author-panel{\n    position:fixed;\n    top:0; left:0; bottom:0;\n    width:380px;\n    max-width:88vw;\n    background:var(--ink-2);\n    border-right:1px solid var(--line);\n    box-shadow:12px 0 28px rgba(0,0,0,.45);\n    z-index:60;\n    transform:translateX(-100%);\n    transition:transform .3s ease;\n    overflow-y:auto;\n    padding:1.5rem 1.35rem 2rem;\n    display:flex;\n    flex-direction:column;\n    gap:1rem;\n  }\n  .author-panel.open{ transform:translateX(0); }\n\n  /* Push the whole page over to the opposite (right) edge of the screen\n     rather than just nudging it — drop the centering max-width so .wrap\n     fills all the way from the panel to the right side of the viewport. */\n  body.author-panel-open .wrap{ margin-left:380px; margin-right:0; max-width:none; }\n\n  /* Header + sort buttons stay pinned to the top of the panel while the\n     story list scrolls underneath. Negative margins cancel the panel's own\n     padding so the opaque background reaches the panel edges. */\n  .author-panel-top{\n    position:sticky;\n    top:-1.5rem;\n    z-index:5;\n    display:flex;\n    flex-direction:column;\n    gap:1rem;\n    margin:-1.5rem -1.35rem 0;\n    padding:1.5rem 1.35rem .75rem;\n    background:var(--ink-2);\n    box-shadow:0 1px 0 var(--line);\n  }\n\n  /* \"Back to top\" button: sits in the header directly below the close button\n     (absolutely positioned so showing it never changes the header height)\n     and fades in once the panel has scrolled. */\n  .author-panel-totop{\n    position:absolute;\n    top:calc(100% + .4rem);\n    right:0;\n    width:30px;\n    height:30px;\n    border-radius:50%;\n    background:none;\n    border:1px solid var(--line);\n    color:var(--muted);\n    cursor:pointer;\n    padding:0;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    line-height:0;\n    opacity:0;\n    transform:translateY(-4px);\n    pointer-events:none;\n    transition:opacity .2s ease, transform .2s ease;\n  }\n  .author-panel-totop.show{ opacity:1; transform:none; pointer-events:auto; }\n  .author-panel-totop:hover{ color:var(--parchment); border-color:var(--brass); }\n  @media (prefers-reduced-motion:reduce){ .author-panel-totop{ transition:none; } }\n\n  .author-panel-head{\n    display:flex;\n    align-items:flex-start;\n    justify-content:space-between;\n    gap:.75rem;\n  }\n  .author-panel-eyebrow{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--brass);\n    margin:0 0 .3rem;\n  }\n  .author-panel-head h2{\n    font-family:'Fraunces', serif;\n    font-style:italic;\n    font-weight:600;\n    font-size:1.25rem;\n    margin:0;\n    line-height:1.25;\n  }\n  .author-panel-namerow{\n    display:flex;\n    align-items:baseline;\n    flex-wrap:wrap;\n    column-gap:.75rem;\n  }\n  .author-panel-link{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    letter-spacing:.05em;\n    color:var(--brass-bright);\n    text-decoration:none;\n    white-space:nowrap;\n    opacity:0;\n    transition:opacity .15s ease;\n  }\n  .author-panel-link:hover{ text-decoration:underline; }\n  /* Revealed when hovering the name row or tabbing to the link; always shown\n     on touch devices, which have no hover. */\n  .author-panel-namerow:hover .author-panel-link,\n  .author-panel-link:focus-visible{ opacity:1; }\n  @media (hover:none){ .author-panel-link{ opacity:1; } }\n  .author-panel-meta{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.7rem;\n    color:var(--muted);\n    margin:.4rem 0 0;\n  }\n  .author-panel-head-actions{\n    display:flex;\n    align-items:center;\n    gap:.4rem;\n    flex-shrink:0;\n    position:relative;\n  }\n  .author-panel-bookmark{\n    flex-shrink:0;\n    width:30px;\n    height:30px;\n    border-radius:50%;\n    background:none;\n    border:1px solid var(--line);\n    color:var(--muted);\n    cursor:pointer;\n    padding:0;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    line-height:0;\n  }\n  .author-panel-bookmark svg{ width:14px; height:14px; display:block; }\n  .author-panel-bookmark:hover{ color:var(--parchment); border-color:var(--brass); }\n  .author-panel-bookmark.active{ color:var(--brass-bright); border-color:var(--brass); }\n  .author-panel-close{\n    flex-shrink:0;\n    width:30px;\n    height:30px;\n    border-radius:50%;\n    background:none;\n    border:1px solid var(--line);\n    color:var(--muted);\n    font-size:1.1rem;\n    line-height:1;\n    cursor:pointer;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n  }\n  .author-panel-close:hover{ color:var(--parchment); border-color:var(--brass); }\n\n  .author-panel-sort{\n    display:flex;\n    flex-wrap:nowrap;\n    gap:.3rem;\n  }\n  .author-sort-btn{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    letter-spacing:.01em;\n    background:none;\n    border:1px solid var(--line);\n    color:var(--muted);\n    padding:.3rem .4rem;\n    min-height:31px;\n    border-radius:2px;\n    cursor:pointer;\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n    flex:1 1 auto;\n    min-width:0;\n    white-space:nowrap;\n    gap:.25rem;\n  }\n  .author-sort-btn:hover{ color:var(--parchment); border-color:var(--brass); }\n  .author-sort-btn.active{\n    background:none;\n    border-color:var(--brass);\n    color:var(--brass-bright);\n    font-weight:500;\n  }\n  .author-sort-btn .arrow{ font-size:.7rem; line-height:1; }\n\n  .author-panel-list{\n    display:flex;\n    flex-direction:column;\n    gap:.3rem;\n    border-top:1px solid var(--line);\n    padding-top:.5rem;\n  }\n  /* Reuses the .author-story-item styling from the full Authors view so an\n     item expands in place to show its synopsis, tags, and chapters. */\n  .author-panel-list .author-story-item{ padding-right:2.9rem; }\n\n  #author-panel-backdrop{\n    position:fixed;\n    inset:0;\n    background:rgba(0,0,0,.5);\n    z-index:55;\n    opacity:0;\n    pointer-events:none;\n    transition:opacity .3s ease;\n  }\n\n  @media (max-width:700px){\n    .author-panel{ width:100%; max-width:100%; }\n    body.author-panel-open .wrap{ margin-left:0; }\n    #author-panel-backdrop.show{ opacity:1; pointer-events:auto; }\n  }\n\n  /* --- Main column controls --- */\n  .controls-main{\n    position:sticky;\n    top:0;\n    z-index:10;\n    background:\n      linear-gradient(var(--ink) 88%, transparent),\n      var(--ink);\n    padding:1.25rem 0 1rem;\n    margin-bottom:1.5rem;\n    border-bottom:1px solid var(--line);\n  }\n\n  @media (max-width:900px){\n    .controls-main{ position:static; background:none; }\n  }\n\n  .search-row{\n    display:flex;\n    gap:.75rem;\n    flex-wrap:wrap;\n    align-items:center;\n  }\n\n  #search{\n    flex:1 1 120px;\n    min-width:0;\n    background:var(--ink-2);\n    border:1px solid var(--line);\n    color:var(--parchment);\n    font-family:'Source Serif 4', Georgia, serif;\n    font-size:1rem;\n    padding:.65rem .9rem;\n    border-radius:2px;\n  }\n  #search::placeholder{ color:var(--muted); }\n  #search:focus-visible{ border-color:var(--brass); }\n\n  .sort-group{\n    display:flex;\n    align-items:center;\n    gap:.5rem;\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.78rem;\n  }\n\n  .sort-group label{ color:var(--muted); }\n\n  select{\n    background:var(--ink-2);\n    border:1px solid var(--line);\n    color:var(--parchment);\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.78rem;\n    padding:.5rem .6rem;\n    border-radius:2px;\n  }\n\n  .mode-toggle{\n    display:inline-flex;\n    border:1px solid var(--line);\n    border-radius:2px;\n    overflow:hidden;\n  }\n  .mode-toggle button{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    letter-spacing:.05em;\n    background:var(--ink-2);\n    color:var(--muted);\n    border:none;\n    padding:.5rem .7rem;\n    cursor:pointer;\n  }\n  .mode-toggle button.active{\n    background:var(--brass);\n    color:var(--ink);\n    font-weight:500;\n  }\n\n  /* --- Sidebar: match toggle --- */\n  .sidebar-top{\n    margin-bottom:1rem;\n    /* Nudges the Match toggle down to line up with the Stories/Authors\n       toggle, which sits vertically centered against the taller search\n       input in its row rather than flush with the top padding. */\n    margin-top:.35rem;\n  }\n  .sidebar-top .sort-group{ justify-content:space-between; width:100%; }\n\n  .tag-hint{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    color:var(--muted);\n    margin:0 0 .8rem;\n    line-height:1.4;\n  }\n\n  /* --- Tag group dropdowns --- */\n  .tag-groups{\n    display:flex;\n    flex-direction:column;\n    gap:.5rem;\n    margin-bottom:1.5rem;\n  }\n\n  .tag-group{\n    border:1px solid var(--line);\n    border-radius:3px;\n    background:var(--ink-2);\n  }\n  .tag-group[open]{ border-color:#4a4130; }\n\n  .tag-group summary{\n    cursor:pointer;\n    list-style:none;\n    padding:.65rem .8rem;\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.76rem;\n    letter-spacing:.03em;\n    color:var(--parchment-dim);\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n  }\n  .tag-group summary::-webkit-details-marker{ display:none; }\n  .tag-group summary:hover{ color:var(--parchment); }\n\n  .summary-right{ display:flex; align-items:center; gap:.5rem; }\n\n  .group-badge{\n    background:var(--brass);\n    color:var(--ink);\n    font-size:.66rem;\n    font-weight:600;\n    padding:.05rem .4rem;\n    border-radius:10px;\n    display:none;\n    line-height:1.4;\n  }\n  .group-badge.show{ display:inline-block; }\n\n  .chevron{\n    color:var(--muted);\n    transition:transform .2s ease;\n    font-size:.7rem;\n  }\n  .tag-group[open] .chevron{ transform:rotate(90deg); }\n\n  .tag-group .tag-row{\n    display:flex;\n    flex-direction:column;\n    gap:.35rem;\n    padding:.5rem .7rem .75rem;\n    border-top:1px solid var(--line);\n  }\n\n  .tag-chip{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    line-height:1.3;\n    background:var(--ink);\n    border:1px solid var(--line);\n    color:var(--parchment-dim);\n    padding:.45rem .6rem;\n    border-radius:2px;\n    cursor:pointer;\n    user-select:none;\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:.6rem;\n    text-align:left;\n  }\n  .tag-chip:hover{ border-color:var(--brass); color:var(--parchment); }\n  .tag-chip.active{\n    background:var(--brass);\n    border-color:var(--brass);\n    color:var(--ink);\n    font-weight:500;\n  }\n  .tag-chip.excluded{\n    background:var(--ink);\n    border-color:#7a2a2a;\n    color:#c98c8c;\n    text-decoration:line-through;\n    text-decoration-color:#7a2a2a;\n  }\n  .tag-chip.excluded:hover{ border-color:#a34848; color:#e0a3a3; }\n  .tag-chip .count{ opacity:.65; font-size:.9em; flex-shrink:0; }\n  .tag-chip.active .count{ opacity:.75; }\n  .tag-chip.excluded .count{ opacity:.6; }\n\n  /* --- Sort dropdowns (sidebar) --- */\n  .sort-content{\n    display:flex;\n    flex-direction:column;\n    gap:.65rem;\n    padding:.6rem .8rem .8rem;\n    border-top:1px solid var(--line);\n  }\n\n  .sort-badge{ text-transform:none; }\n\n  .range-slider{\n    position:relative;\n    height:1.4rem;\n    margin-bottom:.3rem;\n  }\n\n  .range-slider .track{\n    position:absolute;\n    top:50%; left:0; right:0;\n    height:3px;\n    background:var(--line);\n    transform:translateY(-50%);\n    border-radius:2px;\n  }\n  .range-slider .track-fill{\n    position:absolute;\n    top:50%; height:3px;\n    background:var(--brass);\n    transform:translateY(-50%);\n    border-radius:2px;\n  }\n\n  .range-slider input[type=\"range\"]{\n    position:absolute;\n    left:0; top:50%;\n    width:100%;\n    transform:translateY(-50%);\n    margin:0;\n    background:transparent;\n    -webkit-appearance:none;\n    appearance:none;\n    pointer-events:none;\n    height:0;\n  }\n  .range-slider input[type=\"range\"]::-webkit-slider-thumb{\n    pointer-events:auto;\n    -webkit-appearance:none;\n    appearance:none;\n    width:14px; height:14px;\n    border-radius:50%;\n    background:var(--brass-bright);\n    border:2px solid var(--ink);\n    cursor:pointer;\n    margin-top:0;\n  }\n  .range-slider input[type=\"range\"]::-moz-range-thumb{\n    pointer-events:auto;\n    width:14px; height:14px;\n    border-radius:50%;\n    background:var(--brass-bright);\n    border:2px solid var(--ink);\n    cursor:pointer;\n  }\n  .range-slider input[type=\"range\"]::-moz-range-track{ background:transparent; border:none; }\n\n  .range-labels{\n    display:flex;\n    justify-content:space-between;\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.7rem;\n    color:var(--parchment-dim);\n  }\n\n  .clear-link{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.74rem;\n    color:var(--muted);\n    background:none;\n    border:none;\n    text-decoration:underline;\n    text-underline-offset:3px;\n    cursor:pointer;\n    padding:.4rem 0;\n  }\n  .clear-link:hover{ color:var(--parchment); }\n\n  /* Search-scope toggle: same segmented look and size as Stories/Authors.\n     Each button is given the same fixed width those two buttons end up with\n     (their labels are the same length), so Title/Synopsis match instead of\n     sizing to their own text. */\n  /* Slides open/closed when switching between Stories and Authors. The\n     width animates (and the search bar flexes to fill the space); the\n     negative margin cancels the row gap so no empty gap is left behind. */\n  .scope-toggle{\n    max-width:calc(9.35rem + 2px);\n    opacity:1;\n    transition:max-width .3s ease, opacity .2s ease, margin-left .3s ease, border-width .3s ease;\n  }\n  .scope-toggle.collapsed{\n    max-width:0;\n    opacity:0;\n    margin-left:-.75rem;\n    border-width:0;\n    pointer-events:none;\n  }\n  @media (prefers-reduced-motion: reduce){\n    .scope-toggle{ transition:none; }\n  }\n  .scope-toggle button{ width:4.675rem; padding-left:0; padding-right:0; }\n\n  /* --- Results --- */\n  /* minmax(0,1fr), not 1fr: a bare 1fr track can't shrink below its widest\n     unbreakable content, so a long chapter title (plus author credit) in an\n     expanded row would push the whole page wider than a phone screen. */\n  #results{ display:grid; grid-template-columns:minmax(0,1fr); gap:.4rem; }\n\n  .row{\n    display:block;\n    position:relative;\n    padding:.85rem 3.15rem .85rem .95rem;\n    border:1px solid var(--line);\n    border-radius:2px;\n    background:var(--ink-2);\n    margin-bottom:.4rem;\n    cursor:pointer;\n  }\n  .row:hover{ border-color:var(--brass); }\n  .row.expanded{ border-color:var(--brass); }\n\n  .row-top{\n    display:flex;\n    flex-wrap:wrap;\n    align-items:baseline;\n    gap:.5rem;\n  }\n\n  .row .name{\n    font-family:'Fraunces', serif;\n    font-style:italic;\n    font-size:1.08rem;\n    color:var(--parchment);\n    text-decoration:none;\n    flex-shrink:0;\n  }\n\n  /* --- Bookmarks --- */\n  .bookmark-btn{\n    position:absolute;\n    top:-9px;\n    right:1.2rem;\n    width:34px;\n    height:40px;\n    background:var(--ink-3);\n    border:1px solid var(--line);\n    border-top:none;\n    border-radius:0 0 4px 4px;\n    box-shadow:0 4px 7px rgba(0,0,0,.4);\n    color:var(--muted);\n    cursor:pointer;\n    padding:0 0 .4rem;\n    display:flex;\n    align-items:flex-end;\n    justify-content:center;\n    line-height:0;\n    flex-shrink:0;\n    transition:background .15s ease, color .15s ease, border-color .15s ease, transform .1s ease;\n  }\n  .bookmark-btn svg{ width:19px; height:19px; display:block; }\n  .bookmark-btn:hover{ color:var(--brass-bright); border-color:var(--brass); }\n  .bookmark-btn:active{ transform:translateY(1px); }\n  .bookmark-btn.active{ background:var(--brass); border-color:var(--brass); color:var(--ink); }\n  .bookmark-btn.active:hover{ background:var(--brass-bright); border-color:var(--brass-bright); }\n  /* .small variant lives in the author lists (author page + sidebar). Those\n     are scrollable, borderless rows, so the tab hangs from the item's own top\n     edge (top:0, not negative) to avoid being clipped by the scroll area.\n     Same ribbon look as the main list, just a little smaller. */\n  .bookmark-btn.small{\n    top:0; right:.5rem;\n    width:28px; height:38px;\n    background:var(--ink-4);\n    border:1px solid var(--line);\n    border-top:none;\n    border-radius:0 0 4px 4px;\n    box-shadow:0 3px 6px rgba(0,0,0,.4);\n    padding:0 0 .45rem;\n    align-items:flex-end;\n  }\n  .bookmark-btn.small svg{ width:16px; height:16px; }\n  .bookmark-btn.small:hover{ color:var(--brass-bright); border-color:var(--brass); }\n  .bookmark-btn.small.active{ background:var(--brass); border-color:var(--brass); color:var(--ink); }\n  .bookmark-btn.small.active:hover{ background:var(--brass-bright); border-color:var(--brass-bright); }\n\n  .saved-toggle{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.78rem;\n    letter-spacing:.02em;\n    background:var(--ink-2);\n    border:1px solid var(--line);\n    color:var(--muted);\n    padding:.55rem .7rem;\n    border-radius:2px;\n    cursor:pointer;\n    white-space:nowrap;\n    flex-shrink:0;\n    display:inline-flex;\n    align-items:center;\n    gap:.4rem;\n  }\n  .saved-toggle svg{ width:14px; height:14px; flex-shrink:0; }\n  .saved-toggle:hover{ color:var(--parchment); border-color:var(--brass); }\n  .saved-toggle.active{\n    background:var(--brass);\n    border-color:var(--brass);\n    color:var(--ink);\n    font-weight:500;\n  }\n  .saved-toggle.excluded{\n    background:var(--ink);\n    border-color:#7a2a2a;\n    color:#c98c8c;\n  }\n  .saved-toggle.excluded:hover{ border-color:#a34848; color:#e0a3a3; }\n\n  .row .dash, .author-story-item > .row-top .dash{\n    color:var(--line);\n    flex-shrink:0;\n  }\n\n  .row .expand-indicator{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    color:var(--muted);\n    flex-shrink:0;\n  }\n\n  .row .meta{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    color:var(--brass);\n    letter-spacing:.01em;\n    min-width:0;\n  }\n\n  .author-story-item > .row-top .meta{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    color:var(--parchment-dim);\n    letter-spacing:.01em;\n    min-width:0;\n  }\n\n  .row .meta .sep, .author-story-item > .row-top .meta .sep{ color:var(--line); margin:0 .45em; }\n  .row .meta .pending{ color:var(--muted); font-style:italic; }\n\n  /* Top-level story entries in the author view reuse the main list's\n     title-dash-meta header line, just at the smaller author-list scale. */\n  .author-story-item > .row-top{ flex-wrap:wrap; }\n  .author-story-item > .row-top .dash{ display:none; }\n  .author-story-item > .row-top .meta{ flex:0 0 100%; }\n  .author-story-item > .row-top .meta .meta-line{ display:block; }\n  .author-story-item > .row-top .meta .nowrap{ white-space:nowrap; }\n  .author-story-item > .row-top .meta .vsep{\n    display:inline-block;\n    width:3px;\n    height:3px;\n    border-radius:50%;\n    margin:0 .7em;\n    background:var(--brass);\n    opacity:.6;\n    vertical-align:.25em;\n  }\n  .author-story-item > .row-top .name{\n    font-family:'Fraunces', serif;\n    font-style:italic;\n    font-size:.92rem;\n    color:var(--parchment);\n    text-decoration:none;\n    /* May shrink to the item's content box (which stops short of the bookmark\n       tab) and wrap onto further lines, instead of running underneath it. */\n    flex:0 1 auto;\n    min-width:0;\n    max-width:100%;\n    overflow-wrap:break-word;\n  }\n\n  .author-link{\n    font:inherit;\n    color:var(--brass-bright);\n    font-weight:500;\n    background:none;\n    border:none;\n    padding:0;\n    margin:0;\n    cursor:pointer;\n    text-decoration:underline;\n    text-decoration-color:transparent;\n    text-underline-offset:2px;\n    transition:text-decoration-color .15s ease, color .15s ease;\n  }\n  .author-link:hover, .author-link:focus-visible{\n    color:var(--brass-bright);\n    text-decoration-color:var(--brass-bright);\n  }\n\n  /* Story header. The lead block is a wrapping flex row of two items:\n       1. \"Title — by A - B - C\"  (one inline flow; if it's too long for the\n          line, the names that don't fully fit wrap onto lines below it)\n       2. \"Updated · chapters · words\"  (a single item: it sits beside item 1\n          only if everything fits on one line, otherwise it moves down as a\n          whole - below any wrapped author lines, never beside them)\n     \"▾ more\" always stays on the FIRST line and follows the text: it starts\n     at the end of the details, and placeIndicator() (JS) moves it up behind\n     the last author that fits on line 1 when the details have dropped down.\n     If it can't follow any text it pins to the right edge (.pinned). */\n  .story-head{\n    contain:layout;\n    /* keeps \"more\" clear of the bookmark tab hanging in the row's corner */\n    margin-right:.75rem;\n  }\n  .story-lead{\n    display:flex;\n    flex-wrap:wrap;\n    align-items:baseline;\n    column-gap:1rem;\n    row-gap:.15rem;\n    min-width:0;\n  }\n  /* Small base size so wrapped author lines get a compact line box; the\n     title keeps its own (rem-based) size, so line 1 is unchanged. */\n  .story-id{ flex:0 1 auto; min-width:0; max-width:100%; font-size:.72rem; line-height:1.5; }\n  .story-lead .meta{ flex:0 1 auto; }\n  .story-lead .meta .nowrap{ white-space:nowrap; }\n  .story-head .expand-indicator{ white-space:nowrap; margin-left:.6em; }\n  .story-head .expand-indicator.pinned{ float:right; margin-left:.75rem; }\n  /* hidden only until its row has been placed, so it never visibly jumps */\n  .story-head:not(.placed) .expand-indicator{ visibility:hidden; }\n  .story-id .dash{ color:var(--line); font-size:1rem; margin:0 .1em; }\n  .by-chunk{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    letter-spacing:.01em;\n    color:var(--brass);\n    white-space:nowrap;\n  }\n  .by-dash{ color:var(--muted); }\n  /* Dash between the byline and the details (\"Title — by A — Updated ...\"). Only\n     shown while the details sit beside the byline on the same line; placeIndicator()\n     toggles .meta-inline on the header. */\n  .meta-dash{ display:none; color:var(--line); font-size:1rem; margin:0 .4em 0 -.55rem; }\n  .story-head.meta-inline .meta-dash{ display:inline; }\n\n  .row .synopsis{\n    font-size:.88rem;\n    color:var(--parchment-dim);\n    margin:.4rem 0 0;\n    line-height:1.4;\n  }\n\n  .expanded-tags{\n    display:flex;\n    flex-wrap:wrap;\n    gap:.4rem;\n    margin-top:.65rem;\n  }\n  .expanded-tags .tag-chip{\n    display:inline-flex;\n    width:auto;\n    border-radius:20px;\n    padding:.35rem .7rem;\n    font-size:.7rem;\n  }\n\n  /* --- Author view --- */\n  .author-row .expand-indicator{ color:var(--brass-bright); }\n\n  .author-stories{\n    margin-top:.65rem;\n    max-height:320px;\n    overflow-y:auto;\n    border-top:1px solid var(--line);\n    padding-top:.5rem;\n    display:flex;\n    flex-direction:column;\n    gap:.3rem;\n  }\n\n  /* On the author page the sort buttons come first, so the divider goes\n     below them (between the buttons and the story list) instead of above. */\n  .author-stories.has-sort{\n    border-top:none;\n    padding-top:0;\n  }\n  /* Author-page sort buttons: fixed-ish width instead of stretching across\n     the whole row (the sidebar's buttons are unaffected). */\n  .author-row-sort .author-sort-btn{ flex:0 1 9.25rem; }\n  .author-stories.has-sort > .author-row-sort{\n    padding-bottom:.6rem;\n    margin-bottom:.2rem;\n    border-bottom:1px solid var(--line);\n  }\n\n  .author-story-item{\n    display:block;\n    position:relative;\n    padding:.4rem 2.9rem .4rem .2rem;\n    border-radius:2px;\n    cursor:pointer;\n  }\n  .author-story-item:hover{ background:var(--ink-3); }\n  a.author-story-item.chapter-link{ color:inherit; text-decoration:none; }\n  .author-story-item.expanded{ background:var(--ink-3); }\n  /* Chapters live inside an expanded story item, which already uses --ink-3,\n     so the normal hover color was invisible there. Use a lighter shade. */\n  .author-story-item.expanded .chapter-link:hover,\n  .author-story-item.expanded .chapter-link:focus-visible{ background:var(--ink-4); }\n\n  .story-item-top{\n    display:flex;\n    justify-content:space-between;\n    align-items:baseline;\n    gap:.75rem;\n  }\n\n  .author-story-item .story-item-name{\n    font-family:'Fraunces', serif;\n    font-style:italic;\n    font-size:.92rem;\n    color:var(--parchment);\n    text-decoration:none;\n    min-width:0;\n    overflow:hidden;\n    text-overflow:ellipsis;\n    white-space:nowrap;\n  }\n\n  .author-story-item .meta-mini{\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.68rem;\n    color:var(--muted);\n    white-space:nowrap;\n    flex-shrink:0;\n  }\n\n  /* Chapter rows in multi-author stories: \"Author(s) · 1,234 words\".\n     On a wide row it all sits on one line. When the title and credit don't\n     fit side by side (phones, the narrow author panel, long collaborator\n     lists) the credit drops to its own right-aligned line under the title\n     rather than squeezing either one. */\n  .story-item-top.has-credit{\n    flex-wrap:wrap;\n    row-gap:.1rem;\n  }\n  .author-story-item .meta-mini.has-authors{\n    display:flex;\n    align-items:baseline;\n    justify-content:flex-end;\n    flex:0 1 auto;\n    min-width:0;\n    max-width:100%;\n    margin-left:auto;\n    white-space:normal;\n  }\n  .meta-mini .ch-authors{\n    min-width:0;\n    text-align:right;\n    color:var(--parchment-dim);\n  }\n  .meta-mini .ch-name{ white-space:nowrap; }\n  .meta-mini .ch-words{ flex:none; white-space:nowrap; }\n  .meta-mini .ch-dot{\n    flex:none;\n    width:3px;\n    height:3px;\n    margin:0 .7em;\n    border-radius:50%;\n    background:var(--brass);\n    opacity:.6;\n    position:relative;\n    top:-.28em;\n  }\n\n  .author-story-item .synopsis{ margin-top:.4rem; }\n  .author-story-item .expanded-tags{ margin-top:.5rem; }\n\n\n  .read-story-btn{\n    display:inline-flex;\n    align-items:center;\n    gap:.35rem;\n    margin-top:.65rem;\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.72rem;\n    letter-spacing:.05em;\n    background:var(--brass);\n    color:var(--ink);\n    font-weight:500;\n    border:none;\n    border-radius:999px;\n    padding:.5rem 1rem;\n    text-decoration:none;\n    cursor:pointer;\n  }\n  .read-story-btn:hover{ background:var(--brass-bright); }\n\n  .empty-state{\n    text-align:center;\n    padding:3rem 1rem;\n    color:var(--muted);\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.85rem;\n  }\n\n  #sentinel{ height:1px; }\n\n  footer{\n    border-top:1px solid var(--line);\n    margin-top:2.5rem;\n    padding-top:1.25rem;\n    font-family:'IBM Plex Mono', monospace;\n    font-size:.78rem;\n    color:var(--muted);\n    text-align:center;\n  }\n</style>\n<style>html.solo,html.solo body{background:transparent!important}html.solo .wrap{visibility:hidden}html.solo #author-panel-backdrop.show{opacity:1;pointer-events:auto}</style><!--MCO_DATA-->\n</head>\n<body>\n\n<div id=\"author-panel-backdrop\"></div>\n<aside id=\"author-panel\" class=\"author-panel\" aria-hidden=\"true\">\n  <div class=\"author-panel-top\">\n<div class=\"author-panel-head\">\n    <div>\n      <p class=\"author-panel-eyebrow\">Author</p>\n      <div class=\"author-panel-namerow\">\n        <h2 id=\"author-panel-name\"></h2>\n        <a id=\"author-panel-link\" class=\"author-panel-link\" href=\"#\" target=\"_top\" rel=\"noopener noreferrer\" title=\"Open this author's page on mcstories.com\">Author page &#8599;</a>\n      </div>\n      <p class=\"author-panel-meta\" id=\"author-panel-meta\"></p>\n    </div>\n    <div class=\"author-panel-head-actions\">\n      <button type=\"button\" class=\"author-panel-bookmark\" id=\"author-panel-bookmark\" aria-pressed=\"false\" aria-label=\"Bookmark this author\" title=\"Bookmark this author\"></button>\n      <button type=\"button\" class=\"author-panel-close\" id=\"author-panel-close\" aria-label=\"Close\">&times;</button>\n      <button type=\"button\" class=\"author-panel-totop\" id=\"author-panel-totop\" aria-label=\"Scroll to top\" title=\"Scroll to top\" tabindex=\"-1\">\n      <svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 13V3M3.5 7.5 8 3l4.5 4.5\"/></svg>\n    </button>\n    </div>\n  </div>\n  <div class=\"author-panel-sort\" id=\"author-panel-sort\">\n    <button type=\"button\" class=\"author-sort-btn\" data-field=\"title\">Title</button>\n    <button type=\"button\" class=\"author-sort-btn\" data-field=\"added\">Date Added</button>\n    <button type=\"button\" class=\"author-sort-btn\" data-field=\"updated\">Updated</button>\n    <button type=\"button\" class=\"author-sort-btn\" data-field=\"words\">Word Count</button>\n  </div>\n  </div>\n  <div class=\"author-panel-list\" id=\"author-panel-list\"></div>\n</aside>\n\n<div class=\"wrap\">\n\n\n  <header>\n    <p class=\"eyebrow\"><a class=\"back\" id=\"mco-close-link\" href=\"#\">← Back to MCStories</a></p>\n    <h1 id=\"pagetitle\">Browse every story</h1>\n    <p class=\"subhead\" id=\"totalcount\"></p>\n  </header>\n\n  <div class=\"page\">\n\n    <div class=\"main-col\">\n      <div class=\"controls-main\">\n        <div class=\"search-row\">\n          <input type=\"text\" id=\"search\" placeholder=\"Search titles…\" autocomplete=\"off\"/>\n          <div class=\"mode-toggle scope-toggle\" id=\"scope-toggle\" role=\"group\" aria-label=\"Search in\">\n            <button type=\"button\" id=\"scope-title\" class=\"active\">Title</button>\n            <button type=\"button\" id=\"scope-synopsis\">Synopsis</button>\n          </div>\n          <div class=\"mode-toggle\" role=\"group\" aria-label=\"Browse by\">\n            <button type=\"button\" id=\"view-stories\" class=\"active\">Stories</button>\n            <button type=\"button\" id=\"view-authors\">Authors</button>\n          </div>\n          <button type=\"button\" id=\"saved-toggle\" class=\"saved-toggle\" aria-pressed=\"false\"><span class=\"saved-toggle-icon\"></span><span class=\"saved-toggle-label\"></span></button>\n          <button type=\"button\" class=\"clear-link\" id=\"clearall\" hidden>Clear filters</button>\n        </div>\n      </div>\n\n      <div id=\"results\"></div>\n      <div class=\"empty-state\" id=\"emptystate\" hidden>No stories match those filters.</div>\n      <div id=\"sentinel\"></div>\n\n      <footer>\n      </footer>\n    </div>\n\n    <aside class=\"sidebar\">\n      <div class=\"sidebar-top\">\n        <div class=\"sort-group\">\n          <span>Match</span>\n          <div class=\"mode-toggle\" role=\"group\" aria-label=\"Tag match mode\">\n            <button type=\"button\" id=\"mode-and\" class=\"active\">All tags</button>\n            <button type=\"button\" id=\"mode-or\">Any tag</button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"tag-groups\" id=\"sortgroups\">\n\n        <details class=\"tag-group sort-dd\" data-field=\"title\">\n          <summary><span class=\"summary-label\" data-stories-label=\"Sort: Title\" data-authors-label=\"Sort: Author Name\">Sort: Title</span>\n            <span class=\"summary-right\">\n              <span class=\"group-badge sort-badge\" data-field=\"title\"></span>\n              <span class=\"chevron\">▸</span>\n            </span>\n          </summary>\n          <div class=\"sort-content\">\n            <div class=\"mode-toggle dir-toggle\" data-field=\"title\" role=\"group\" aria-label=\"Title sort direction\">\n              <button type=\"button\" data-dir=\"desc\">A → Z</button>\n              <button type=\"button\" data-dir=\"asc\">Z → A</button>\n            </div>\n          </div>\n        </details>\n\n        <details class=\"tag-group sort-dd\" data-field=\"words\">\n          <summary><span class=\"summary-label\" data-stories-label=\"Sort: Word Count\" data-authors-label=\"Sort: Total Words\">Sort: Word Count</span>\n            <span class=\"summary-right\">\n              <span class=\"group-badge sort-badge\" data-field=\"words\"></span>\n              <span class=\"chevron\">▸</span>\n            </span>\n          </summary>\n          <div class=\"sort-content\">\n            <div class=\"mode-toggle dir-toggle\" data-field=\"words\" role=\"group\" aria-label=\"Word count sort direction\">\n              <button type=\"button\" data-dir=\"desc\">High → Low</button>\n              <button type=\"button\" data-dir=\"asc\">Low → High</button>\n            </div>\n            <div class=\"range-slider\" id=\"slider-words\">\n              <div class=\"track\"></div>\n              <div class=\"track-fill\"></div>\n              <input type=\"range\" class=\"thumb-min\"/>\n              <input type=\"range\" class=\"thumb-max\"/>\n            </div>\n            <div class=\"range-labels\"><span id=\"words-min-label\"></span><span id=\"words-max-label\"></span></div>\n          </div>\n        </details>\n\n        <details class=\"tag-group sort-dd\" data-field=\"added\" open>\n          <summary><span class=\"summary-label\" data-stories-label=\"Sort: Date Added\" data-authors-label=\"Sort: Latest Story Added\">Sort: Date Added</span>\n            <span class=\"summary-right\">\n              <span class=\"group-badge sort-badge\" data-field=\"added\"></span>\n              <span class=\"chevron\">▸</span>\n            </span>\n          </summary>\n          <div class=\"sort-content\">\n            <div class=\"mode-toggle dir-toggle\" data-field=\"added\" role=\"group\" aria-label=\"Date added sort direction\">\n              <button type=\"button\" data-dir=\"desc\">High → Low</button>\n              <button type=\"button\" data-dir=\"asc\">Low → High</button>\n            </div>\n            <div class=\"range-slider\" id=\"slider-added\">\n              <div class=\"track\"></div>\n              <div class=\"track-fill\"></div>\n              <input type=\"range\" class=\"thumb-min\"/>\n              <input type=\"range\" class=\"thumb-max\"/>\n            </div>\n            <div class=\"range-labels\"><span id=\"added-min-label\"></span><span id=\"added-max-label\"></span></div>\n          </div>\n        </details>\n\n        <details class=\"tag-group sort-dd\" data-field=\"updated\">\n          <summary><span class=\"summary-label\" data-stories-label=\"Sort: Date Updated\" data-authors-label=\"Sort: Latest Story Updated\">Sort: Date Updated</span>\n            <span class=\"summary-right\">\n              <span class=\"group-badge sort-badge\" data-field=\"updated\"></span>\n              <span class=\"chevron\">▸</span>\n            </span>\n          </summary>\n          <div class=\"sort-content\">\n            <div class=\"mode-toggle dir-toggle\" data-field=\"updated\" role=\"group\" aria-label=\"Date updated sort direction\">\n              <button type=\"button\" data-dir=\"desc\">High → Low</button>\n              <button type=\"button\" data-dir=\"asc\">Low → High</button>\n            </div>\n            <div class=\"range-slider\" id=\"slider-updated\">\n              <div class=\"track\"></div>\n              <div class=\"track-fill\"></div>\n              <input type=\"range\" class=\"thumb-min\"/>\n              <input type=\"range\" class=\"thumb-max\"/>\n            </div>\n            <div class=\"range-labels\"><span id=\"updated-min-label\"></span><span id=\"updated-max-label\"></span></div>\n          </div>\n        </details>\n\n      </div>\n\n      <div class=\"tag-groups\" id=\"taggroups\"></div>\n    </aside>\n\n  </div>\n</div>\n\n<script>\n(function(){\n  var resultsEl = document.getElementById('results');\n\n  resultsEl.innerHTML = '<div class=\"empty-state\" id=\"loadingstate\">Loading stories…</div>';\n\n  Promise.resolve()\n    .then(function(){\n      var payload = JSON.parse(document.getElementById('mco-data').textContent);\n      if (payload.error) throw new Error(payload.error);\n      return payload.data;\n    })\n    .then(function(data){\n      init(data.stories, data.tags);\n    })\n    .catch(function(err){\n      resultsEl.innerHTML = '<div class=\"empty-state\">Couldn\\u2019t load story data (' + escapeErr(err.message) +\n        '). Check that the data URL in the userscript is reachable.</div>';\n    });\n\n  function escapeErr(str){\n    var d = document.createElement('div');\n    d.textContent = str;\n    return d.innerHTML;\n  }\n\n  function init(stories, tagDefs){\n  var BOOKMARK_KEY = 'storyArchive.bookmarks.v1';\n  // Authors have their own, separate saved list (keyed by author name).\n  var AUTHOR_BOOKMARK_KEY = 'storyArchive.authorBookmarks.v1';\n\n  function loadBookmarks(key){\n    try {\n      var raw = localStorage.getItem(key);\n      return new Set(raw ? JSON.parse(raw) : []);\n    } catch(e){ return new Set(); }\n  }\n  var BASE_URL = 'https://mcstories.com/';\n  function storyUrl(href){ return BASE_URL + href; }\n  function readHref(s){ return (s.chapters && s.chapters.length && s.chapters[0].href) ? s.chapters[0].href : s.href; }\n  var bookmarks = loadBookmarks(BOOKMARK_KEY);\n  var authorBookmarks = loadBookmarks(AUTHOR_BOOKMARK_KEY);\n  function saveBookmarks(){\n    try { localStorage.setItem(BOOKMARK_KEY, JSON.stringify(Array.from(bookmarks))); } catch(e){}\n  }\n  function saveAuthorBookmarks(){\n    try { localStorage.setItem(AUTHOR_BOOKMARK_KEY, JSON.stringify(Array.from(authorBookmarks))); } catch(e){}\n  }\n  function toggleAuthorBookmark(name){\n    if (!name) return;\n    if (authorBookmarks.has(name)) authorBookmarks.delete(name);\n    else authorBookmarks.add(name);\n    saveAuthorBookmarks();\n    updateSavedToggleLabel();\n    updateAuthorPanelBookmark();\n  }\n  function toggleBookmark(href){\n    if (!href) return;\n    if (bookmarks.has(href)) bookmarks.delete(href);\n    else bookmarks.add(href);\n    saveBookmarks();\n    updateSavedToggleLabel();\n  }\n  function bookmarkBtnHtml(href, extraClass){\n    var on = bookmarks.has(href);\n    var icon = on\n      ? '<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>'\n      : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>';\n    return '<button type=\"button\" class=\"bookmark-btn' + (on ? ' active' : '') + (extraClass ? ' ' + extraClass : '') +\n      '\" data-href=\"' + escapeHtml(href) + '\" aria-pressed=\"' + on + '\" aria-label=\"' +\n      (on ? 'Remove bookmark' : 'Bookmark this story') + '\" title=\"' +\n      (on ? 'Remove bookmark' : 'Bookmark this story') + '\">' + icon + '</button>';\n  }\n\n  // Bookmark tab for an author row (same look as a story's tab).\n  function authorBookmarkBtnHtml(name){\n    var on = authorBookmarks.has(name);\n    var icon = on\n      ? '<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>'\n      : '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>';\n    var label = on ? 'Remove author bookmark' : 'Bookmark this author';\n    return '<button type=\"button\" class=\"bookmark-btn author-bookmark-btn' + (on ? ' active' : '') +\n      '\" data-author=\"' + escapeHtml(name) + '\" aria-pressed=\"' + on + '\" aria-label=\"' + label + '\" title=\"' + label + '\">' + icon + '</button>';\n  }\n\n  var tagLabels = {};\n  var tagCounts = {};\n  Object.keys(tagDefs).forEach(function(code){\n    tagLabels[code] = tagDefs[code].label;\n    tagCounts[code] = tagDefs[code].count;\n  });\n\n  var TAG_GROUPS = [\n    { name: 'Relationships', tags: ['mf','ff','mm'] },\n    { name: 'Power Dynamics', tags: ['fd','md','ds','hm','nc'] },\n    { name: 'Kink & Fetish', tags: ['bd','ft','ex','la','ws','sc'] },\n    { name: 'Taboo', tags: ['in','be','ca'] },\n    { name: 'Genre & Setting', tags: ['sf','rb','ts','cb','fu'] },\n    { name: 'Other', tags: ['hu','ma','gr'] }\n  ];\n\n  var chips = {};\n  var taggroups = document.getElementById('taggroups');\n  var groupBadges = {};\n\n  function cycleTagState(code){\n    var chip = chips[code];\n    if (!chip) return;\n    var next = chip.dataset.state === 'none' ? 'include'\n              : chip.dataset.state === 'include' ? 'exclude'\n              : 'none';\n    chip.dataset.state = next;\n    chip.classList.toggle('active', next === 'include');\n    chip.classList.toggle('excluded', next === 'exclude');\n  }\n\n  function buildChip(code){\n    var chip = document.createElement('button');\n    chip.type = 'button';\n    chip.className = 'tag-chip';\n    chip.dataset.code = code;\n    chip.dataset.state = 'none';\n    chip.innerHTML = '<span class=\"label\">' + tagLabels[code] + '</span><span class=\"count\">' + (tagCounts[code] || 0) + '</span>';\n    chip.addEventListener('click', function(){\n      cycleTagState(code);\n      updateGroupBadges();\n      render();\n    });\n    chips[code] = chip;\n    return chip;\n  }\n\n  TAG_GROUPS.forEach(function(group, gi){\n    var details = document.createElement('details');\n    details.className = 'tag-group';\n\n    var summary = document.createElement('summary');\n    var badge = document.createElement('span');\n    badge.className = 'group-badge';\n    var right = document.createElement('span');\n    right.className = 'summary-right';\n    right.appendChild(badge);\n    var chevron = document.createElement('span');\n    chevron.className = 'chevron';\n    chevron.textContent = '\\u25b8';\n    right.appendChild(chevron);\n\n    summary.textContent = group.name;\n    summary.appendChild(right);\n    details.appendChild(summary);\n\n    var row = document.createElement('div');\n    row.className = 'tag-row';\n    group.tags.forEach(function(code){\n      if (!(code in tagLabels)) return;\n      row.appendChild(buildChip(code));\n    });\n    details.appendChild(row);\n\n    taggroups.appendChild(details);\n    groupBadges[group.name] = { badge: badge, tags: group.tags };\n  });\n\n  var tagCodes = Object.keys(chips);\n\n  function updateGroupBadges(){\n    Object.keys(groupBadges).forEach(function(name){\n      var info = groupBadges[name];\n      var n = info.tags.filter(function(t){ return chips[t] && chips[t].dataset.state !== 'none'; }).length;\n      if (n > 0){\n        info.badge.textContent = n;\n        info.badge.classList.add('show');\n      } else {\n        info.badge.classList.remove('show');\n      }\n    });\n  }\n\n  var searchInput = document.getElementById('search');\n  var modeAnd = document.getElementById('mode-and');\n  var modeOr = document.getElementById('mode-or');\n  var viewStoriesBtn = document.getElementById('view-stories');\n  var viewAuthorsBtn = document.getElementById('view-authors');\n  var clearBtn = document.getElementById('clearall');\n  var resultsEl = document.getElementById('results');\n  var emptyEl = document.getElementById('emptystate');\n  var totalEl = document.getElementById('totalcount');\n  var pageTitleEl = document.getElementById('pagetitle');\n  var sentinel = document.getElementById('sentinel');\n  var savedToggle = document.getElementById('saved-toggle');\n  var savedToggleIcon = savedToggle.querySelector('.saved-toggle-icon');\n  var savedToggleLabel = savedToggle.querySelector('.saved-toggle-label');\n\n  var scopeToggle = document.getElementById('scope-toggle');\n  var scopeTitleBtn = document.getElementById('scope-title');\n  var scopeSynopsisBtn = document.getElementById('scope-synopsis');\n  // 'title' = search story titles only (default), 'synopsis' = search synopses only\n  var searchScope = 'title';\n  function updateScopeToggle(){\n    var isSyn = searchScope === 'synopsis';\n    scopeTitleBtn.classList.toggle('active', !isSyn);\n    scopeSynopsisBtn.classList.toggle('active', isSyn);\n    if (viewMode !== 'authors') searchInput.placeholder = isSyn ? 'Search synopses…' : 'Search titles…';\n    updateScopeCollapse();\n  }\n\n  // Author view always searches author names, so the toggle doesn't apply\n  // there and slides closed (the CSS transition on .scope-toggle does the\n  // sliding). Author rows no longer expand in place, so rebuilding the list\n  // is cheap and the slide can simply run as soon as the view changes.\n  function updateScopeCollapse(){\n    var collapse = viewMode === 'authors';\n    scopeToggle.classList.toggle('collapsed', collapse);\n    // Keep the collapsed buttons out of tab order / screen readers.\n    if (collapse) scopeToggle.setAttribute('inert', ''); else scopeToggle.removeAttribute('inert');\n    scopeToggle.setAttribute('aria-hidden', collapse);\n  }\n  function setScope(scope){\n    if (searchScope === scope) return;\n    searchScope = scope;\n    clearTimeout(debounceTimer);\n    render();\n  }\n  scopeTitleBtn.addEventListener('click', function(){ setScope('title'); });\n  scopeSynopsisBtn.addEventListener('click', function(){ setScope('synopsis'); });\n\n  var BOOKMARK_ICON_OUTLINE = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>';\n  var BOOKMARK_ICON_FILLED = '<svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M6 3a2 2 0 0 0-2 2v16l8-5 8 5V5a2 2 0 0 0-2-2z\"/></svg>';\n\n  // 'none' = no filter, 'include' = saved only, 'exclude' = hide saved.\n  // The Saved button follows the current view: in Stories it filters/counts\n  // saved stories, in Authors it filters/counts saved authors. Each view\n  // remembers its own filter state when you switch back and forth.\n  var savedStateByMode = {stories: 'none', authors: 'none'};\n  function currentSavedKey(){ return viewMode === 'authors' ? 'authors' : 'stories'; }\n  function updateSavedToggleLabel(){\n    var key = currentSavedKey();\n    var state = savedStateByMode[key];\n    var n = (key === 'authors' ? authorBookmarks : bookmarks).size;\n    savedToggle.classList.toggle('active', state === 'include');\n    savedToggle.classList.toggle('excluded', state === 'exclude');\n    savedToggle.setAttribute('aria-pressed', state === 'include');\n    savedToggleIcon.innerHTML = state === 'include' ? BOOKMARK_ICON_FILLED : BOOKMARK_ICON_OUTLINE;\n    var what = key === 'authors' ? 'Saved authors' : 'Saved stories';\n    var mode = state === 'include' ? 'showing only saved' : state === 'exclude' ? 'hiding saved' : 'click to filter';\n    savedToggle.title = what + ' (' + mode + ')';\n    savedToggle.setAttribute('aria-label', what + ': ' + n + ', ' + mode);\n    savedToggleLabel.textContent = n;\n  }\n  updateSavedToggleLabel();\n  savedToggle.addEventListener('click', function(){\n    var key = currentSavedKey();\n    var st = savedStateByMode[key];\n    savedStateByMode[key] = st === 'none' ? 'include' : st === 'include' ? 'exclude' : 'none';\n    updateSavedToggleLabel();\n    render();\n  });\n\n  // Everyone credited on a story, in byline order. `author` (first author) is\n  // kept in the data for compatibility; `authors` is the full list.\n  function authorsOf(s){\n    return (s.authors && s.authors.length) ? s.authors : (s.author ? [s.author] : []);\n  }\n\n  // True when a co-authored story's chapters do NOT all share the same credit\n  // (anthologies, tag-team serials). Only then are authors shown per chapter;\n  // when every chapter is by the same people, the byline already says it all.\n  function hasDifferingChapterCredits(s){\n    var base = authorsOf(s);\n    if (base.length < 2 || !s.chapters) return false;\n    var first = null;\n    for (var i = 0; i < s.chapters.length; i++){\n      var ch = s.chapters[i];\n      var key = ((ch.authors && ch.authors.length) ? ch.authors : base).slice().sort().join('\\u0000');\n      if (first === null) first = key;\n      else if (key !== first) return true;\n    }\n    return false;\n  }\n\n  // How many of a story's words an author wrote. In a story with differing\n  // chapter credits that is just their chapters (so an anthology's total isn't\n  // credited in full to every contributor); otherwise it's the whole story.\n  function authorWords(s, name){\n    if (!('words' in s)) return 0;\n    if (!s._chapterCredits) return s.words;\n    var base = authorsOf(s);\n    return s.chapters.reduce(function(sum, ch){\n      var list = (ch.authors && ch.authors.length) ? ch.authors : base;\n      return list.indexOf(name) !== -1 ? sum + ch.words : sum;\n    }, 0);\n  }\n\n  var totalAuthorCount = Object.keys(stories.reduce(function(acc, s){\n    authorsOf(s).forEach(function(a){ acc[a] = 1; });\n    return acc;\n  }, {})).length;\n\n  var viewMode = 'stories';\n\n  // \"Last Updated\" comes from the data itself: the newest date_added / date_updated\n  // of any story, so it follows stories.json with no manual edit.\n  var lastUpdatedText = (function(){\n    var newest = '';\n    stories.forEach(function(s){\n      if (s.date_added && s.date_added > newest) newest = s.date_added;\n      if (s.date_updated && s.date_updated > newest) newest = s.date_updated;\n    });\n    var p = newest.split('-');\n    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n    var mon = months[parseInt(p[1], 10) - 1];\n    if (p.length !== 3 || !mon) return '';\n    return ' Last Updated ' + mon + ' ' + parseInt(p[2], 10) + ', ' + p[0];\n  })();\n\n  function updateTotalText(){\n    if (viewMode === 'authors'){\n      pageTitleEl.textContent = 'Browse every author';\n      totalEl.textContent = totalAuthorCount.toLocaleString() + ' authors. Click one to see everything they\\u2019ve written.';\n    } else {\n      pageTitleEl.textContent = 'Browse every story';\n      totalEl.textContent = stories.length.toLocaleString() + ' stories.' + lastUpdatedText;\n    }\n  }\n  updateTotalText();\n\n  function updateSortLabels(){\n    document.querySelectorAll('.summary-label').forEach(function(el){\n      el.textContent = viewMode === 'authors' ? el.dataset.authorsLabel : el.dataset.storiesLabel;\n    });\n  }\n\n  viewStoriesBtn.addEventListener('click', function(){\n    if (viewMode === 'stories') return;\n    closeAuthorPanel();\n    viewMode = 'stories';\n    viewStoriesBtn.classList.add('active');\n    viewAuthorsBtn.classList.remove('active');\n    searchInput.placeholder = 'Search stories…';\n    clearTimeout(debounceTimer);\n    updateTotalText();\n    updateSortLabels();\n    render();\n  });\n\n  viewAuthorsBtn.addEventListener('click', function(){\n    if (viewMode === 'authors') return;\n    closeAuthorPanel();\n    viewMode = 'authors';\n    viewAuthorsBtn.classList.add('active');\n    viewStoriesBtn.classList.remove('active');\n    searchInput.placeholder = 'Search authors…';\n    clearTimeout(debounceTimer);\n    updateTotalText();\n    updateSortLabels();\n    render();\n  });\n\n  // Jump from a story's \"by AuthorName\" link straight to that author's\n  // full portfolio in the Authors view, pre-expanded and scrolled into\n  // view. Used by the mini-panel's \"View all works\" button.\n  function goToAuthor(name){\n    authorPanelExpandedSet.forEach(function(href){ authorStoryExpandedSet.add(href); });\n    closeAuthorPanel();\n    viewMode = 'authors';\n    viewAuthorsBtn.classList.add('active');\n    viewStoriesBtn.classList.remove('active');\n    searchInput.placeholder = 'Search authors…';\n    clearTimeout(debounceTimer);\n    searchInput.value = name;\n    authorExpandedSet.add(name);\n    updateTotalText();\n    updateSortLabels();\n    render();\n    requestAnimationFrame(function(){\n      var rows = resultsEl.querySelectorAll('.author-row');\n      for (var i = 0; i < rows.length; i++){\n        if (rows[i].dataset.author === name){\n          rows[i].scrollIntoView({ behavior: 'smooth', block: 'start' });\n          break;\n        }\n      }\n    });\n  }\n\n  // --- Author mini-portfolio side panel ---\n  // Opened from a story's \"by AuthorName\" link. This is a quick peek: it\n  // does NOT touch the current search, filters, or view mode, so browsing\n  // picks up right where it was left when the panel closes. It stays tied\n  // to whichever story row triggered it and auto-closes the moment that\n  // story is collapsed again (see the row-collapse handling below).\n  var authorPanelEl = document.getElementById('author-panel');\n  var authorPanelBackdrop = document.getElementById('author-panel-backdrop');\n  var authorPanelNameEl = document.getElementById('author-panel-name');\n  var authorPanelMetaEl = document.getElementById('author-panel-meta');\n  var authorPanelListEl = document.getElementById('author-panel-list');\n  var authorPanelCloseBtn = document.getElementById('author-panel-close');\n  var authorPanelTriggerHref = null;\n  var authorPanelName = null;\n  // The sidebar panel gets its own expanded-story tracking, separate from\n  // authorStoryExpandedSet (used by the full Authors view), so opening the\n  // panel always starts collapsed rather than remembering the last session.\n  var authorPanelExpandedSet = new Set();\n\n  // Simple 3-state sort for the panel's own story list: click a field once\n  // for descending, twice for ascending, a third time to clear back to the\n  // default (most-recent-date-added) order. Independent of the main list's\n  // sort/filter state.\n  var authorPanelSort = {field: 'added', dir: 'desc'};\n  var authorPanelSortEl = document.getElementById('author-panel-sort');\n\n  function authorPanelSortValue(s, field){\n    if (field === 'title') return stripArticle(s.title);\n    if (field === 'added') return (s._addedDays === null || s._addedDays === undefined) ? -Infinity : s._addedDays;\n    if (field === 'updated') return (s._updatedDays === null || s._updatedDays === undefined) ? -Infinity : s._updatedDays;\n    if (field === 'words') return ('words' in s) ? s.words : -Infinity;\n  }\n\n  function updateAuthorPanelSortButtons(){\n    authorPanelSortEl.querySelectorAll('.author-sort-btn').forEach(function(btn){\n      var field = btn.dataset.field;\n      var label = btn.textContent.replace(/^[\\u2191\\u2193]\\s*/, '').trim();\n      if (field === authorPanelSort.field){\n        btn.classList.add('active');\n        var arrow = authorPanelSort.dir === 'asc' ? '\\u2191' : '\\u2193';\n        btn.innerHTML = '<span class=\"arrow\">' + arrow + '</span>' + escapeHtml(label);\n      } else {\n        btn.classList.remove('active');\n        btn.textContent = label;\n      }\n    });\n  }\n\n  authorPanelSortEl.addEventListener('click', function(e){\n    var btn = e.target.closest('.author-sort-btn');\n    if (!btn) return;\n    var field = btn.dataset.field;\n    if (authorPanelSort.field !== field){\n      authorPanelSort = {field: field, dir: 'desc'};\n    } else if (authorPanelSort.dir === 'desc'){\n      authorPanelSort.dir = 'asc';\n    } else {\n      authorPanelSort = {field: null, dir: null};\n    }\n    updateAuthorPanelSortButtons();\n    renderAuthorPanelList();\n  });\n\n  function renderAuthorPanelList(){\n    if (!authorPanelName) return;\n    var authored = stories.filter(function(s){ return authorsOf(s).indexOf(authorPanelName) !== -1; }).slice().sort(function(a,b){\n      var va = authorPanelSortValue(a, 'added'), vb = authorPanelSortValue(b, 'added');\n      return va < vb ? 1 : (va > vb ? -1 : 0);\n    });\n    if (authorPanelSort.field){\n      var field = authorPanelSort.field, dir = authorPanelSort.dir;\n      authored.sort(function(a,b){\n        var va = authorPanelSortValue(a, field), vb = authorPanelSortValue(b, field);\n        var cmp = va < vb ? -1 : (va > vb ? 1 : 0);\n        return dir === 'asc' ? cmp : -cmp;\n      });\n    }\n    authorPanelListEl.innerHTML = authored.map(function(s){\n      return storyItemHtml(s, authorPanelExpandedSet.has(s.href));\n    }).join('');\n  }\n\n  var authorPanelToTopBtn = document.getElementById('author-panel-totop');\n  function updateAuthorPanelToTop(){\n    var on = authorPanelEl.scrollTop > 0;\n    authorPanelToTopBtn.classList.toggle('show', on);\n    authorPanelToTopBtn.tabIndex = on ? 0 : -1;\n  }\n  authorPanelEl.addEventListener('scroll', updateAuthorPanelToTop, {passive:true});\n  authorPanelToTopBtn.addEventListener('click', function(){\n    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n    authorPanelEl.scrollTo({top:0, behavior: reduce ? 'auto' : 'smooth'});\n  });\n\n  function openAuthorPanel(name, triggerHref){\n    authorPanelName = name;\n    authorPanelTriggerHref = triggerHref || null;\n    authorPanelExpandedSet = new Set();\n    authorPanelSort = {field: 'added', dir: 'desc'};\n    updateAuthorPanelSortButtons();\n\n    var authored = stories.filter(function(s){ return authorsOf(s).indexOf(name) !== -1; });\n    var totalWords = authored.reduce(function(sum,s){ return sum + authorWords(s, name); }, 0);\n\n    authorPanelNameEl.textContent = name;\n    // Author pages on the site are named after the author with spaces as dashes.\n    document.getElementById('author-panel-link').href =\n      'https://mcstories.com/Authors/' + encodeURIComponent(name.trim().replace(/\\s+/g, '-')) + '.html';\n    authorPanelMetaEl.textContent = authored.length.toLocaleString() + (authored.length === 1 ? ' story' : ' stories') +\n      ' \\u00b7 ' + totalWords.toLocaleString() + ' words total';\n    renderAuthorPanelList();\n    updateAuthorPanelBookmark();\n\n    authorPanelEl.classList.add('open');\n    authorPanelEl.setAttribute('aria-hidden', 'false');\n    authorPanelBackdrop.classList.add('show');\n    document.body.classList.add('author-panel-open');\n    authorPanelEl.scrollTop = 0;\n    updateAuthorPanelToTop();\n  }\n\n  function closeAuthorPanel(){\n    if (!authorPanelName) return;\n    authorPanelName = null;\n    authorPanelTriggerHref = null;\n    authorPanelExpandedSet = new Set();\n    authorPanelEl.classList.remove('open');\n    authorPanelEl.setAttribute('aria-hidden', 'true');\n    authorPanelBackdrop.classList.remove('show');\n    document.body.classList.remove('author-panel-open');\n    if (soloMode) window.parent.postMessage({mco:'close'}, '*');\n  }\n\n  var authorPanelBookmarkBtn = document.getElementById('author-panel-bookmark');\n  function updateAuthorPanelBookmark(){\n    if (!authorPanelName) return;\n    var on = authorBookmarks.has(authorPanelName);\n    var label = on ? 'Remove author bookmark' : 'Bookmark this author';\n    authorPanelBookmarkBtn.classList.toggle('active', on);\n    authorPanelBookmarkBtn.setAttribute('aria-pressed', on);\n    authorPanelBookmarkBtn.setAttribute('aria-label', label);\n    authorPanelBookmarkBtn.title = label;\n    authorPanelBookmarkBtn.innerHTML = on ? BOOKMARK_ICON_FILLED : BOOKMARK_ICON_OUTLINE;\n  }\n  authorPanelBookmarkBtn.addEventListener('click', function(){\n    toggleAuthorBookmark(authorPanelName);\n    // If the Authors list is what's showing behind the panel, keep its tabs\n    // (and any Saved filter) in step.\n    if (viewMode === 'authors'){\n      if (savedStateByMode.authors === 'none') renderAuthorList(currentAuthorList);\n      else render();\n    }\n  });\n  authorPanelCloseBtn.addEventListener('click', closeAuthorPanel);\n  authorPanelBackdrop.addEventListener('click', closeAuthorPanel);\n  document.addEventListener('keydown', function(e){\n    if (e.key === 'Escape') closeAuthorPanel();\n  });\n\n  // Expand a story inside the panel to show its synopsis/tags/chapters.\n  // The panel uses its own authorPanelExpandedSet (reset each time the\n  // panel opens) rather than authorStoryExpandedSet, which belongs to the\n  // full Authors view - see goToAuthor() for how the two are reconciled\n  // when jumping from the panel to the full portfolio.\n  authorPanelListEl.addEventListener('click', function(e){\n    var bookmarkBtn = e.target.closest('.bookmark-btn');\n    if (bookmarkBtn){\n      toggleBookmark(bookmarkBtn.dataset.href);\n      renderAuthorPanelList();\n      return;\n    }\n    var tagBtn = e.target.closest('.tag-chip');\n    if (tagBtn){\n      // The panel's own story pool ignores tag filters entirely (it always\n      // shows everything by this author), so there's nothing to exempt here\n      // - just update the shared tag state and refresh both the panel and\n      // the main page so everything stays in sync, without collapsing.\n      cycleTagState(tagBtn.dataset.code);\n      updateGroupBadges();\n      render();\n      renderAuthorPanelList();\n      return;\n    }\n    if (e.target.closest('a.chapter-link') || e.target.closest('.author-stories') || e.target.closest('.read-story-btn')) return;\n    var item = e.target.closest('.author-story-item');\n    if (!item) return;\n    var href = item.dataset.href;\n    if (authorPanelExpandedSet.has(href)) authorPanelExpandedSet.delete(href);\n    else authorPanelExpandedSet.add(href);\n    renderAuthorPanelList();\n  });\n\n  authorPanelListEl.addEventListener('keydown', function(e){\n    if (e.key !== 'Enter' && e.key !== ' ') return;\n    var item = e.target.closest('.author-story-item:not(.chapter-link)');\n    if (!item || e.target !== item) return;\n    e.preventDefault();\n    var href = item.dataset.href;\n    if (authorPanelExpandedSet.has(href)) authorPanelExpandedSet.delete(href);\n    else authorPanelExpandedSet.add(href);\n    renderAuthorPanelList();\n  });\n\n  var matchMode = 'and';\n  modeAnd.addEventListener('click', function(){ matchMode='and'; modeAnd.classList.add('active'); modeOr.classList.remove('active'); render(); });\n  modeOr.addEventListener('click', function(){ matchMode='or'; modeOr.classList.add('active'); modeAnd.classList.remove('active'); render(); });\n\n  var sortField = 'added';\n  var sortDir = 'desc';\n\n  var sortDirLabels = { desc: '↓ High → Low', asc: '↑ Low → High' };\n\n  function updateSortUI(){\n    document.querySelectorAll('.dir-toggle').forEach(function(toggle){\n      var field = toggle.dataset.field;\n      toggle.querySelectorAll('button').forEach(function(btn){\n        btn.classList.toggle('active', field === sortField && btn.dataset.dir === sortDir);\n      });\n    });\n    document.querySelectorAll('.sort-badge').forEach(function(badge){\n      var isActive = badge.dataset.field === sortField;\n      badge.classList.toggle('show', isActive);\n      if (isActive) badge.textContent = sortDirLabels[sortDir];\n    });\n  }\n\n  document.querySelectorAll('.dir-toggle').forEach(function(toggle){\n    var field = toggle.dataset.field;\n    toggle.querySelectorAll('button').forEach(function(btn){\n      btn.addEventListener('click', function(){\n        sortField = field;\n        sortDir = btn.dataset.dir;\n        updateSortUI();\n        render();\n      });\n    });\n  });\n\n  updateSortUI();\n\n  function activeTags(){\n    return tagCodes.filter(function(c){ return chips[c].dataset.state === 'include'; });\n  }\n\n  function excludedTags(){\n    return tagCodes.filter(function(c){ return chips[c].dataset.state === 'exclude'; });\n  }\n\n  function stripArticle(t){\n    var low = t.toLowerCase();\n    if (low.indexOf('the ') === 0) return low.slice(4);\n    if (low.indexOf('an ') === 0) return low.slice(3);\n    if (low.indexOf('a ') === 0) return low.slice(2);\n    return low;\n  }\n\n  function toDays(iso){\n    if (!iso) return null;\n    var t = Date.parse(iso + 'T00:00:00Z');\n    if (isNaN(t)) return null;\n    return Math.floor(t / 86400000);\n  }\n\n  function fmtDate(iso){\n    if (!iso) return null;\n    var parts = iso.split('-');\n    if (parts.length !== 3) return iso;\n    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n    var y = parts[0], m = parseInt(parts[1],10)-1, d = parseInt(parts[2],10);\n    return d + ' ' + months[m] + ' ' + y;\n  }\n\n  function fmtDays(days){\n    var d = new Date(days * 86400000);\n    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];\n    return d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear();\n  }\n\n  stories.forEach(function(s){\n    s._addedDays = toDays(s.date_added);\n    s._updatedDays = toDays(s.date_updated);\n    s._chapterCredits = hasDifferingChapterCredits(s);\n  });\n\n  function buildSlider(containerId, minVal, maxVal, formatFn, labelMinEl, labelMaxEl, onChange){\n    var container = document.getElementById(containerId);\n    var thumbMin = container.querySelector('.thumb-min');\n    var thumbMax = container.querySelector('.thumb-max');\n    var fill = container.querySelector('.track-fill');\n\n    thumbMin.min = minVal; thumbMin.max = maxVal; thumbMin.value = minVal; thumbMin.step = 1;\n    thumbMax.min = minVal; thumbMax.max = maxVal; thumbMax.value = maxVal; thumbMax.step = 1;\n\n    function update(){\n      var lo = parseInt(thumbMin.value, 10);\n      var hi = parseInt(thumbMax.value, 10);\n      if (lo > hi){\n        var tmp = lo; lo = hi; hi = tmp;\n      }\n      var range = maxVal - minVal || 1;\n      var pctLo = (lo - minVal) / range * 100;\n      var pctHi = (hi - minVal) / range * 100;\n      fill.style.left = pctLo + '%';\n      fill.style.width = (pctHi - pctLo) + '%';\n      labelMinEl.textContent = formatFn(lo);\n      labelMaxEl.textContent = formatFn(hi);\n      return {lo: lo, hi: hi};\n    }\n\n    var state = update();\n\n    function handleInput(){\n      state = update();\n      onChange(state.lo, state.hi, state.lo === minVal && state.hi === maxVal);\n    }\n\n    thumbMin.addEventListener('input', handleInput);\n    thumbMax.addEventListener('input', handleInput);\n\n    return {\n      reset: function(){ thumbMin.value = minVal; thumbMax.value = maxVal; state = update(); },\n      isFull: function(){ return state.lo === minVal && state.hi === maxVal; },\n      getState: function(){ return state; }\n    };\n  }\n\n  var wordVals = stories.filter(function(s){ return 'words' in s; }).map(function(s){ return s.words; });\n  var wMin = wordVals.length ? Math.min.apply(null, wordVals) : 0;\n  var wMax = wordVals.length ? Math.max.apply(null, wordVals) : 0;\n\n  var addedVals = stories.filter(function(s){ return s._addedDays !== null; }).map(function(s){ return s._addedDays; });\n  var aMin = addedVals.length ? Math.min.apply(null, addedVals) : 0;\n  var aMax = addedVals.length ? Math.max.apply(null, addedVals) : 0;\n\n  var updatedVals = stories.filter(function(s){ return s._updatedDays !== null; }).map(function(s){ return s._updatedDays; });\n  var uMin = updatedVals.length ? Math.min.apply(null, updatedVals) : 0;\n  var uMax = updatedVals.length ? Math.max.apply(null, updatedVals) : 0;\n\n  var wordFilter = {lo: wMin, hi: wMax, active: false};\n  var addedFilter = {lo: aMin, hi: aMax, active: false};\n  var updatedFilter = {lo: uMin, hi: uMax, active: false};\n\n  var wordsSlider = buildSlider('slider-words', wMin, wMax,\n    function(v){ return v.toLocaleString() + ' words'; },\n    document.getElementById('words-min-label'), document.getElementById('words-max-label'),\n    function(lo, hi, isFull){ wordFilter = {lo: lo, hi: hi, active: !isFull}; debounceRender(); });\n\n  var addedSlider = buildSlider('slider-added', aMin, aMax,\n    fmtDays,\n    document.getElementById('added-min-label'), document.getElementById('added-max-label'),\n    function(lo, hi, isFull){ addedFilter = {lo: lo, hi: hi, active: !isFull}; debounceRender(); });\n\n  var updatedSlider = buildSlider('slider-updated', uMin, uMax,\n    fmtDays,\n    document.getElementById('updated-min-label'), document.getElementById('updated-max-label'),\n    function(lo, hi, isFull){ updatedFilter = {lo: lo, hi: hi, active: !isFull}; debounceRender(); });\n\n  var sliderDebounce;\n  function debounceRender(){\n    clearTimeout(sliderDebounce);\n    sliderDebounce = setTimeout(render, 60);\n  }\n\n  var pageSize = 150;\n  var shown = pageSize;\n  var io = new IntersectionObserver(function(entries){\n    if (entries[0].isIntersecting){\n      shown += pageSize;\n      if (viewMode === 'authors'){\n        renderAuthorList(currentAuthorList);\n      } else {\n        renderList(currentFiltered);\n      }\n    }\n  });\n  io.observe(sentinel);\n\n  var currentFiltered = stories;\n  var currentAuthorList = [];\n\n  function applyFilters(){\n    var q = searchInput.value.trim().toLowerCase();\n    var active = activeTags();\n    var excluded = excludedTags();\n\n    return stories.filter(function(s){\n      if (viewMode === 'authors'){\n        // Authors view: \"Saved\" and the name search are applied per author\n        // after grouping (see authorEntryMatches), since one story can now\n        // belong to several authors who don't all match.\n      } else {\n        var ss = savedStateByMode.stories;\n        if (ss === 'include' && !bookmarks.has(s.href)) return false;\n        if (ss === 'exclude' && bookmarks.has(s.href)) return false;\n      }\n\n      if (q){\n        if (viewMode === 'authors'){\n          // matched per author, after grouping\n        } else {\n          var haystack = searchScope === 'synopsis' ? (s.synopsis || '') : s.title;\n          if (haystack.toLowerCase().indexOf(q) === -1) return false;\n        }\n      }\n\n      if (active.length > 0){\n        var tagMatch = matchMode === 'and'\n          ? active.every(function(t){ return s.tags.indexOf(t) !== -1; })\n          : active.some(function(t){ return s.tags.indexOf(t) !== -1; });\n        if (!tagMatch) return false;\n      }\n\n      if (excluded.length > 0 && !exemptFromExclusion.has(s.href)){\n        var hasExcluded = excluded.some(function(t){ return s.tags.indexOf(t) !== -1; });\n        if (hasExcluded) return false;\n      }\n\n      if (wordFilter.active){\n        if (!('words' in s) || s.words < wordFilter.lo || s.words > wordFilter.hi) return false;\n      }\n      if (addedFilter.active){\n        if (s._addedDays === null || s._addedDays < addedFilter.lo || s._addedDays > addedFilter.hi) return false;\n      }\n      if (updatedFilter.active){\n        if (s._updatedDays === null || s._updatedDays < updatedFilter.lo || s._updatedDays > updatedFilter.hi) return false;\n      }\n\n      return true;\n    });\n  }\n\n  function sortStoriesList(list){\n    var field = sortField;\n    return list.slice().sort(function(a,b){\n      var cmp;\n      if (field === 'title'){\n        var ka = stripArticle(a.title), kb = stripArticle(b.title);\n        cmp = ka < kb ? -1 : (ka > kb ? 1 : 0);\n      } else if (field === 'added'){\n        var da = (a._addedDays === null) ? -Infinity : a._addedDays;\n        var db = (b._addedDays === null) ? -Infinity : b._addedDays;\n        cmp = da - db;\n      } else if (field === 'updated'){\n        var ua = (a._updatedDays === null) ? -Infinity : a._updatedDays;\n        var ub = (b._updatedDays === null) ? -Infinity : b._updatedDays;\n        cmp = ua - ub;\n      } else if (field === 'words'){\n        var wa = ('words' in a) ? a.words : -Infinity;\n        var wb = ('words' in b) ? b.words : -Infinity;\n        cmp = wa - wb;\n      }\n      return sortDir === 'desc' ? -cmp : cmp;\n    });\n  }\n\n  function filterStories(){\n    return sortStoriesList(applyFilters());\n  }\n\n  // Author-level filters for the Authors tab: the \"Saved\" toggle and the\n  // name search (both formerly applied to a story's single author).\n  function authorEntryMatches(name, q){\n    var as = savedStateByMode.authors;\n    if (as === 'include' && !authorBookmarks.has(name)) return false;\n    if (as === 'exclude' && authorBookmarks.has(name)) return false;\n    if (q && name.toLowerCase().indexOf(q) === -1) return false;\n    return true;\n  }\n\n  function buildAuthorList(storyPool){\n    var map = {};\n    storyPool.forEach(function(s){\n      authorsOf(s).forEach(function(a){\n        if (!map[a]) map[a] = [];\n        map[a].push(s);\n      });\n    });\n    return Object.keys(map).map(function(name){\n      var arr = map[name].slice().sort(function(a,b){\n        var da = (a._addedDays === null) ? -Infinity : a._addedDays;\n        var db = (b._addedDays === null) ? -Infinity : b._addedDays;\n        return db - da;\n      });\n      var totalWords = arr.reduce(function(sum,s){ return sum + authorWords(s, name); }, 0);\n      var latestAdded = arr.reduce(function(m,s){ return (s._addedDays !== null && (m === null || s._addedDays > m)) ? s._addedDays : m; }, null);\n      var latestUpdated = arr.reduce(function(m,s){ return (s._updatedDays !== null && (m === null || s._updatedDays > m)) ? s._updatedDays : m; }, null);\n      return { name: name, stories: arr, totalWords: totalWords, latestAdded: latestAdded, latestUpdated: latestUpdated, count: arr.length };\n    });\n  }\n\n  function sortAuthorList(list){\n    var field = sortField;\n    return list.slice().sort(function(a,b){\n      var cmp;\n      if (field === 'title'){\n        var ka = a.name.toLowerCase(), kb = b.name.toLowerCase();\n        cmp = ka < kb ? -1 : (ka > kb ? 1 : 0);\n      } else if (field === 'added'){\n        var da = (a.latestAdded === null) ? -Infinity : a.latestAdded;\n        var db = (b.latestAdded === null) ? -Infinity : b.latestAdded;\n        cmp = da - db;\n      } else if (field === 'updated'){\n        var ua = (a.latestUpdated === null) ? -Infinity : a.latestUpdated;\n        var ub = (b.latestUpdated === null) ? -Infinity : b.latestUpdated;\n        cmp = ua - ub;\n      } else if (field === 'words'){\n        cmp = a.totalWords - b.totalWords;\n      }\n      return sortDir === 'desc' ? -cmp : cmp;\n    });\n  }\n\n  function truncate(str, n){\n    if (str.length <= n) return str;\n    var cut = str.slice(0, n);\n    var lastSpace = cut.lastIndexOf(' ');\n    return cut.slice(0, lastSpace > 0 ? lastSpace : n) + '\\u2026';\n  }\n\n  var expandedSet = new Set();\n  var authorExpandedSet = new Set();\n  var authorStoryExpandedSet = new Set();\n  // Per-author sort state for the sort buttons inside each expanded author\n  // section on the main Authors view - independent of the side panel's own\n  // authorPanelSort, and independent per author so expanding several authors\n  // at once keeps their own sort choices.\n  var authorRowSort = {};\n\n  function authorRowSortButtonsHtml(name){\n    var sort = authorRowSort[name] || {field: 'added', dir: 'desc'};\n    var fields = [\n      {field: 'title', label: 'Title'},\n      {field: 'added', label: 'Date Added'},\n      {field: 'updated', label: 'Updated'},\n      {field: 'words', label: 'Word Count'}\n    ];\n    var btns = fields.map(function(f){\n      if (f.field === sort.field){\n        var arrow = sort.dir === 'asc' ? '\\u2191' : '\\u2193';\n        return '<button type=\"button\" class=\"author-sort-btn active\" data-field=\"' + f.field + '\"><span class=\"arrow\">' + arrow + '</span>' + escapeHtml(f.label) + '</button>';\n      }\n      return '<button type=\"button\" class=\"author-sort-btn\" data-field=\"' + f.field + '\">' + escapeHtml(f.label) + '</button>';\n    }).join('');\n    return '<div class=\"author-panel-sort author-row-sort\" data-author=\"' + escapeHtml(name) + '\">' + btns + '</div>';\n  }\n  // Stories currently exempt from tag-exclusion filtering: when a user\n  // excludes a tag from within a story's own expanded tag list, that story\n  // would otherwise vanish out from under them mid-click. Exempting it here\n  // keeps it visible until they deliberately collapse the entry, at which\n  // point the exclusion takes effect normally.\n  var exemptFromExclusion = new Set();\n\n  function tagButtonHtml(code){\n    var label = tagLabels[code] || code;\n    var chip = chips[code];\n    var state = chip ? chip.dataset.state : 'none';\n    var cls = 'tag-chip' + (state === 'include' ? ' active' : state === 'exclude' ? ' excluded' : '');\n    return '<button type=\"button\" class=\"' + cls + '\" data-code=\"' + code + '\">' + escapeHtml(label) + '</button>';\n  }\n\n  // Author credit for chapter rows. Only stories whose chapters have\n  // DIFFERENT credits get one (see hasDifferingChapterCredits); solo stories\n  // and fully co-written stories (same people on every chapter) keep plain\n  // rows, because the story's byline already says who wrote it.\n  // Lists are joined the way the archive writes bylines: \"A and B\",\n  // \"A; B and C\" (semicolons, since some names contain commas).\n  // Each name is its own no-wrap span so a long credit only ever wraps\n  // between names, never in the middle of one (\"G-\" / \"Man001\").\n  function creditHtml(list){\n    var names = list.map(function(a){ return '<span class=\"ch-name\">' + escapeHtml(a) + '</span>'; });\n    if (names.length <= 1) return names[0] || '';\n    return names.slice(0, -1).join(names.length > 2 ? '; ' : '') + ' and ' + names[names.length - 1];\n  }\n\n  // One chapter's title line: name on the left, \"[authors ·] N words\" on the right.\n  function chapterTopHtml(s, ch){\n    var name = '<span class=\"story-item-name\">' + escapeHtml(ch.name) + '</span>';\n    var words = ch.words.toLocaleString() + ' words';\n    if (!s._chapterCredits){\n      return '<div class=\"story-item-top\">' + name + '<span class=\"meta-mini\">' + words + '</span></div>';\n    }\n    var credit = creditHtml((ch.authors && ch.authors.length) ? ch.authors : s.authors);\n    return '<div class=\"story-item-top has-credit\">' + name +\n      '<span class=\"meta-mini has-authors\">' +\n        '<span class=\"ch-authors\">' + credit + '</span>' +\n        '<span class=\"ch-dot\" aria-hidden=\"true\"></span>' +\n        '<span class=\"ch-words\">' + words + '</span>' +\n      '</span>' +\n    '</div>';\n  }\n\n  // \"by A - B - C\": each name is its own link (opens that author's panel).\n  // A name and the dash after it are one no-wrap unit, so a long list wraps\n  // onto further lines only between names, with dashes ending a line.\n  // Returns inline chunks that sit right after the title in the header.\n  function bylineHtml(s){\n    var list = authorsOf(s);\n    if (!list.length) return '';\n    var chunks = list.map(function(name, i){\n      return '<span class=\"by-chunk\">' + (i === 0 ? 'by&nbsp;' : '') +\n        '<button type=\"button\" class=\"author-link\" data-author=\"' + escapeHtml(name) + '\">' + escapeHtml(name) + '</button>' +\n        (i < list.length - 1 ? '<span class=\"by-dash\" aria-hidden=\"true\">&nbsp;-</span>' : '') +\n      '</span>';\n    });\n    return chunks.join(' ');\n  }\n\n  // --- Keeping \"more\" on the title's line, following the text -------------\n  // CSS can't put an element right after whatever happens to end line 1, so\n  // this measures each header and moves the indicator:\n  //   1. Details beside the authors (all on one line): it stays at the end\n  //      of the details - nothing to do.\n  //   2. Details dropped to their own line: it goes behind the last author\n  //      that still fits on line 1 together with it (authors that don't fit\n  //      wrap below, as before).\n  //   3. Nothing on line 1 can carry it (e.g. a title that itself wraps):\n  //      it pins to the right edge of line 1 - \"its wall\".\n  function sameLine(rect, centerY){\n    return Math.abs((rect.top + rect.bottom) / 2 - centerY) < 8;\n  }\n\n  function placeIndicator(head){\n    var more = head.querySelector('.expand-indicator');\n    if (!more) return;\n    var id = head.querySelector('.story-id');\n    var meta = head.querySelector('.meta');\n    var nameEl = id.querySelector('.name');\n    var dash = id.querySelector('.dash');\n    var chunks = id.querySelectorAll('.by-chunk');\n\n    // Start from home (end of details) so re-measuring after a resize is clean.\n    more.classList.remove('pinned');\n    var oldBreak = id.querySelector('.by-break');\n    if (oldBreak) oldBreak.parentNode.removeChild(oldBreak);\n    meta.appendChild(more);\n\n    // 1. Details share the title's flex line: everything fits on one line.\n    //    Measure with the byline-to-details dash visible; keep it only if that\n    //    still fits beside the byline, otherwise hide it (details wrap below).\n    head.classList.add('meta-inline');\n    if (meta.getBoundingClientRect().top < id.getBoundingClientRect().bottom - 1) return;\n    head.classList.remove('meta-inline');\n\n    // Line 1 = the first line of the title.\n    var first = nameEl.getClientRects()[0];\n    if (!first) return;\n    var lineY = (first.top + first.bottom) / 2;\n\n    // Which author chunks are on line 1 (they're no-wrap, so one rect each)?\n    var last = -1;\n    for (var i = 0; i < chunks.length; i++){\n      if (sameLine(chunks[i].getBoundingClientRect(), lineY)) last = i; else break;\n    }\n    // Try behind the last chunk on line 1; if \"more\" doesn't fit there too,\n    // that chunk drops below and we try the one before it, and so on.\n    for (var k = last; k >= -1; k--){\n      if (k >= 0){\n        chunks[k].appendChild(more);\n      } else if (dash){\n        // Not even the first author fits together with \"more\": it stays up\n        // beside the title and every author moves to the line below.\n        dash.parentNode.insertBefore(more, dash.nextSibling);\n        var br = document.createElement('br');\n        br.className = 'by-break';\n        more.parentNode.insertBefore(br, more.nextSibling);\n      } else break;\n      if (sameLine(more.getBoundingClientRect(), lineY)) return;\n      if (k < 0){ var b2 = id.querySelector('.by-break'); if (b2) b2.parentNode.removeChild(b2); }\n    }\n    // 3. Nothing fits: pin it to the right edge of the first line.\n    more.classList.add('pinned');\n    id.insertBefore(more, id.firstChild);\n  }\n\n  // Placing is cheap but not free, so it's done in two tiers:\n  //   - rows on (or near) the screen are placed SYNCHRONOUSLY, in the same\n  //     task as the DOM change that needs it, i.e. before the browser paints.\n  //     Without this, every re-render (expanding/collapsing a story, resizing,\n  //     opening the author panel) would show a frame or two of unplaced rows:\n  //     \"more\" hidden and multi-author text in its un-measured layout.\n  //   - everything further away is placed lazily as it scrolls toward the\n  //     screen (the list can grow to thousands of rows).\n  var PLACE_MARGIN = 700;   // px above/below the viewport that count as \"near\"\n  var placeEpoch = 0;       // bumped whenever line breaks may have changed\n\n  function ensurePlaced(head){\n    if (head._placeEpoch === placeEpoch) return;     // already right for this width\n    placeIndicator(head);\n    head._placeEpoch = placeEpoch;\n    head.classList.add('placed');\n  }\n\n  function placeNearViewport(){\n    var heads = resultsEl.querySelectorAll('.story-head');\n    var n = heads.length;\n    if (!n) return;\n    var vh = window.innerHeight;\n    // Rows are in document order, so binary-search the first one that reaches\n    // the near zone instead of measuring thousands of rows.\n    var lo = 0, hi = n;\n    while (lo < hi){\n      var mid = (lo + hi) >> 1;\n      if (heads[mid].getBoundingClientRect().bottom < -PLACE_MARGIN) lo = mid + 1; else hi = mid;\n    }\n    // Read first, then write: collect the near rows before moving anything.\n    var near = [];\n    for (var i = lo; i < n; i++){\n      if (heads[i].getBoundingClientRect().top > vh + PLACE_MARGIN) break;\n      near.push(heads[i]);\n    }\n    near.forEach(ensurePlaced);\n  }\n\n  // Everything else is placed as it scrolls near. Rows stay observed so a row\n  // that was placed for an older width is fixed when it comes back into range.\n  var placeIO = new IntersectionObserver(function(entries){\n    entries.forEach(function(en){\n      if (en.isIntersecting) ensurePlaced(en.target);\n    });\n  }, { rootMargin: PLACE_MARGIN + 'px 0px' });\n\n  function observeHeads(){\n    placeIO.disconnect();\n    resultsEl.querySelectorAll('.story-head').forEach(function(h){ placeIO.observe(h); });\n  }\n\n  // Line breaks change when the column width changes (window resize, author\n  // panel sliding open/closed) and when web fonts arrive. ResizeObserver runs\n  // before paint, so near rows are re-placed without ever showing stale text.\n  function relayoutIndicators(){\n    placeEpoch++;\n    placeNearViewport();\n  }\n  if (window.ResizeObserver){\n    var lastResultsWidth = resultsEl.clientWidth;\n    new ResizeObserver(function(){\n      var w = resultsEl.clientWidth;\n      if (w !== lastResultsWidth){ lastResultsWidth = w; relayoutIndicators(); }\n    }).observe(resultsEl);\n  }\n  if (document.fonts){\n    if (document.fonts.ready) document.fonts.ready.then(relayoutIndicators);\n    if (document.fonts.addEventListener) document.fonts.addEventListener('loadingdone', relayoutIndicators);\n  }\n\n  function renderList(list){\n    var slice = list.slice(0, shown);\n    resultsEl.innerHTML = slice.map(function(s){\n      var metaHtml, synopsisHtml = '', bylineInline = '';\n      var isExpanded = expandedSet.has(s.href);\n\n      if ('words' in s){\n        var bits = [];\n        bylineInline = bylineHtml(s);\n        var added = fmtDate(s.date_added);\n        var updated = fmtDate(s.date_updated);\n        if (updated) bits.push('Updated ' + updated);\n        else if (added) bits.push('Added ' + added);\n        var chapCount = s.chapters ? s.chapters.length : 0;\n        bits.push(chapCount + (chapCount === 1 ? ' chapter' : ' chapters'));\n        bits.push(s.words.toLocaleString() + ' words');\n        // Each detail is a no-wrap unit so \"7 chapters\" never splits; the\n        // <wbr> after each dot is the only place the line may break.\n        metaHtml = bits.map(function(b){ return '<span class=\"nowrap\">' + b + '</span>'; })\n                       .join('<span class=\"sep\">\\u00b7</span><wbr>');\n        if (s.synopsis){\n          var text = isExpanded ? s.synopsis : truncate(s.synopsis, 220);\n          synopsisHtml = '<p class=\"synopsis\">' + escapeHtml(text) + '</p>';\n        }\n      } else {\n        metaHtml = '<span class=\"pending\">details not yet available</span>';\n      }\n\n      if (isExpanded){\n        if (s.tags && s.tags.length){\n          synopsisHtml += '<div class=\"expanded-tags\">' + s.tags.map(tagButtonHtml).join('') + '</div>';\n        }\n        synopsisHtml += '<a class=\"read-story-btn\" href=\"' + storyUrl(readHref(s)) + '\" target=\"_top\" rel=\"noopener noreferrer\">Read story \\u2192</a>';\n        if (s.chapters && s.chapters.length){\n          synopsisHtml += '<div class=\"author-stories\">' + s.chapters.map(function(ch){\n            return '<a class=\"author-story-item chapter-link\" href=\"' + storyUrl(ch.href) + '\" target=\"_top\" rel=\"noopener noreferrer\">' +\n              chapterTopHtml(s, ch) +\n            '</a>';\n          }).join('') + '</div>';\n        }\n      }\n\n      var indicator = s.synopsis ? (isExpanded ? '\\u25b4 less' : '\\u25be more') : '';\n      var titleHtml = '<span class=\"name\">' + escapeHtml(s.title) + '</span>';\n\n      return '<div class=\"row' + (isExpanded ? ' expanded' : '') + '\" data-href=\"' + escapeHtml(s.href) + '\" tabindex=\"0\" role=\"button\" aria-expanded=\"' + isExpanded + '\">' +\n        bookmarkBtnHtml(s.href) +\n        '<div class=\"story-head\">' +\n          '<div class=\"story-lead\">' +\n            '<div class=\"story-id\">' + titleHtml +\n              (bylineInline ? ' <span class=\"dash\">\\u2014</span> ' + bylineInline : '') +\n            '</div>' +\n            '<span class=\"meta\">' + (bylineInline ? '<span class=\"meta-dash\" aria-hidden=\"true\">\\u2014</span>' : '') + metaHtml +\n              (indicator ? '<span class=\"expand-indicator\">' + indicator + '</span>' : '') +\n            '</span>' +\n          '</div>' +\n        '</div>' +\n        synopsisHtml +\n      '</div>';\n    }).join('');\n    placeNearViewport();   // before paint: nothing on screen is ever unplaced\n    observeHeads();\n    emptyEl.hidden = list.length !== 0;\n  }\n\n  // Renders one expandable story entry used both in the full Authors view\n  // and the author mini-panel, so expanding a story shows the same\n  // synopsis, tags, and chapter list in either place.\n  function storyItemHtml(s, isItemExpanded){\n    // Line 1: date added · date updated. Line 2: chapter count · word count. Each line\n    // is its own block with no-wrap pieces so \"1 chapter\" never splits.\n    var addedStr = fmtDate(s.date_added);\n    var chapCount = s.chapters ? s.chapters.length : 0;\n    var line2Bits = [chapCount + (chapCount === 1 ? ' chapter' : ' chapters')];\n    if ('words' in s) line2Bits.push(s.words.toLocaleString() + ' words');\n    var metaHtml = '';\n    var updatedStr = fmtDate(s.date_updated);\n    var line1Bits = [];\n    if (addedStr) line1Bits.push('Added ' + addedStr);\n    if (updatedStr) line1Bits.push('Updated ' + updatedStr);\n    if (line1Bits.length){\n      metaHtml += '<span class=\"meta-line\">' +\n        line1Bits.map(function(b){ return '<span class=\"nowrap\">' + b + '</span>'; })\n                 .join('<span class=\"vsep\" aria-hidden=\"true\"></span>') +\n        '</span>';\n    }\n    metaHtml += '<span class=\"meta-line\">' +\n      line2Bits.map(function(b){ return '<span class=\"nowrap\">' + b + '</span>'; })\n               .join('<span class=\"vsep\" aria-hidden=\"true\"></span>') +\n      '</span>';\n    var extra = '';\n    if (isItemExpanded){\n      var synHtml = s.synopsis ? '<p class=\"synopsis\">' + escapeHtml(s.synopsis) + '</p>' : '';\n      var tagsHtml = (s.tags && s.tags.length)\n        ? '<div class=\"expanded-tags\">' + s.tags.map(tagButtonHtml).join('') + '</div>'\n        : '';\n      var chaptersHtml = '';\n      if (s.chapters && s.chapters.length){\n        chaptersHtml = '<div class=\"author-stories\">' + s.chapters.map(function(ch){\n          return '<a class=\"author-story-item chapter-link\" href=\"' + storyUrl(ch.href) + '\" target=\"_top\" rel=\"noopener noreferrer\">' +\n            chapterTopHtml(s, ch) +\n          '</a>';\n        }).join('') + '</div>';\n      }\n      extra = synHtml + tagsHtml + '<a class=\"read-story-btn\" href=\"' + storyUrl(readHref(s)) + '\" target=\"_top\" rel=\"noopener noreferrer\">Read story \\u2192</a>' + chaptersHtml;\n    }\n    var headHtml = '<div class=\"row-top\">' +\n      '<span class=\"name\">' + escapeHtml(s.title) + '</span>' +\n      '<span class=\"dash\">\\u2014</span>' +\n      '<span class=\"meta\">' + metaHtml + '</span>' +\n    '</div>';\n    return '<div class=\"author-story-item' + (isItemExpanded ? ' expanded' : '') + '\" data-href=\"' + escapeHtml(s.href) + '\" tabindex=\"0\" role=\"button\" aria-expanded=\"' + isItemExpanded + '\">' +\n      bookmarkBtnHtml(s.href, 'small') +\n      headHtml +\n      extra +\n    '</div>';\n  }\n\n  function renderAuthorList(list){\n    var slice = list.slice(0, shown);\n\n    // Re-rendering replaces .author-stories (an internally-scrolling list),\n    // which would otherwise reset its scroll position to the top. Capture\n    // and restore it so expanding/collapsing a story doesn't lose your place.\n    var scrollPositions = {};\n    resultsEl.querySelectorAll('.author-row').forEach(function(row){\n      var inner = row.querySelector('.author-stories');\n      if (inner) scrollPositions[row.dataset.author] = inner.scrollTop;\n    });\n\n    resultsEl.innerHTML = slice.map(function(entry){\n      var isExpanded = false; // rows never expand; clicking opens the sidebar\n\n      var bits = [];\n      bits.push(entry.count + (entry.count === 1 ? ' story' : ' stories'));\n      bits.push(entry.totalWords.toLocaleString() + ' words total');\n      if (entry.latestAdded !== null) bits.push('Latest ' + fmtDays(entry.latestAdded));\n      var metaHtml = bits.join('<span class=\"sep\">\\u00b7</span>');\n\n      var indicator = 'view stories \\u203a';\n\n      var storiesHtml = '';\n      if (isExpanded){\n        var rowSort = authorRowSort[entry.name];\n        var rowStories = entry.stories;\n        if (rowSort && rowSort.field){\n          rowStories = rowStories.slice().sort(function(a,b){\n            var va = authorPanelSortValue(a, rowSort.field), vb = authorPanelSortValue(b, rowSort.field);\n            var cmp = va < vb ? -1 : (va > vb ? 1 : 0);\n            return rowSort.dir === 'asc' ? cmp : -cmp;\n          });\n        }\n        storiesHtml = '<div class=\"author-stories has-sort\">' + authorRowSortButtonsHtml(entry.name) +\n          rowStories.map(function(s){\n            return storyItemHtml(s, authorStoryExpandedSet.has(s.href));\n          }).join('') + '</div>';\n      }\n\n      return '<div class=\"row author-row' + (isExpanded ? ' expanded' : '') + '\" data-author=\"' + escapeHtml(entry.name) + '\" tabindex=\"0\" role=\"button\" aria-expanded=\"' + isExpanded + '\">' +\n        authorBookmarkBtnHtml(entry.name) +\n        '<div class=\"row-top\">' +\n          '<span class=\"name\">' + escapeHtml(entry.name) + '</span>' +\n          '<span class=\"dash\">\\u2014</span>' +\n          '<span class=\"meta\">' + metaHtml + ' <span class=\"expand-indicator\">' + indicator + '</span></span>' +\n        '</div>' +\n        storiesHtml +\n      '</div>';\n    }).join('');\n\n    resultsEl.querySelectorAll('.author-row').forEach(function(row){\n      var pos = scrollPositions[row.dataset.author];\n      if (pos){\n        var inner = row.querySelector('.author-stories');\n        if (inner) inner.scrollTop = pos;\n      }\n    });\n\n    emptyEl.hidden = list.length !== 0;\n  }\n\n  resultsEl.addEventListener('click', function(e){\n    var authorLink = e.target.closest('.author-link');\n    if (authorLink){\n      e.stopPropagation();\n      var linkRow = authorLink.closest('.row');\n      openAuthorPanel(authorLink.dataset.author, linkRow ? linkRow.dataset.href : null);\n      return;\n    }\n\n    var bookmarkBtn = e.target.closest('.bookmark-btn');\n    if (bookmarkBtn){\n      if (bookmarkBtn.classList.contains('author-bookmark-btn')){\n        toggleAuthorBookmark(bookmarkBtn.dataset.author);\n        // With no Saved filter on, just redraw the rows in place (keeps the\n        // list as far down as it's been loaded); otherwise re-filter.\n        if (savedStateByMode.authors === 'none') renderAuthorList(currentAuthorList);\n        else render();\n        return;\n      }\n      toggleBookmark(bookmarkBtn.dataset.href);\n      render();\n      return;\n    }\n\n    if (viewMode === 'authors'){\n      var authorRow = e.target.closest('.author-row');\n      if (!authorRow) return;\n\n      var rowSortBtn = e.target.closest('.author-row-sort .author-sort-btn');\n      if (rowSortBtn){\n        e.stopPropagation();\n        var rowSortName = authorRow.dataset.author;\n        var field = rowSortBtn.dataset.field;\n        var current = authorRowSort[rowSortName] || {field: 'added', dir: 'desc'};\n        if (current.field !== field){\n          authorRowSort[rowSortName] = {field: field, dir: 'desc'};\n        } else if (current.dir === 'desc'){\n          authorRowSort[rowSortName] = {field: field, dir: 'asc'};\n        } else {\n          delete authorRowSort[rowSortName];\n        }\n        renderAuthorList(currentAuthorList);\n        return;\n      }\n\n      var tagBtn2 = e.target.closest('.tag-chip');\n      if (tagBtn2){\n        var ownerItem2 = tagBtn2.closest('.author-story-item[data-href]');\n        cycleTagState(tagBtn2.dataset.code);\n        updateGroupBadges();\n        // Same exploratory exemption as the main list: don't let a story\n        // vanish out of its author's list mid-click just because you\n        // excluded one of its own tags.\n        if (ownerItem2) exemptFromExclusion.add(ownerItem2.dataset.href);\n        render();\n        return;\n      }\n\n      var storyItem = e.target.closest('.author-story-item:not(.chapter-link)');\n      if (storyItem){\n        if (e.target.closest('a.chapter-link') || e.target.closest('.read-story-btn')) return; // let chapter links navigate\n        var storyHref = storyItem.dataset.href;\n        if (authorStoryExpandedSet.has(storyHref)){\n          authorStoryExpandedSet.delete(storyHref);\n          if (exemptFromExclusion.has(storyHref)){\n            exemptFromExclusion.delete(storyHref);\n            render();\n            return;\n          }\n        } else {\n          authorStoryExpandedSet.add(storyHref);\n        }\n        renderAuthorList(currentAuthorList);\n        return;\n      }\n\n      if (e.target.closest('.author-stories')){\n        return; // clicked empty space in the scroll area, not on an item - ignore so scrolling never closes anything\n      }\n      // Authors no longer expand in place; the sidebar is the author page.\n      openAuthorPanel(authorRow.dataset.author, null);\n      return;\n    }\n\n    var tagBtn = e.target.closest('.tag-chip');\n    if (tagBtn){\n      var ownerRow = tagBtn.closest('.row[data-href]');\n      cycleTagState(tagBtn.dataset.code);\n      updateGroupBadges();\n      // Clicking a tag from within a story's own expanded tag list is\n      // exploratory - keep that story visible even if the tag is now\n      // excluded, so it doesn't disappear mid-click. It'll be re-filtered\n      // normally once the user collapses it.\n      if (ownerRow) exemptFromExclusion.add(ownerRow.dataset.href);\n      render();\n      return;\n    }\n    if (e.target.closest('.author-stories') || e.target.closest('.read-story-btn')) return;\n    var row = e.target.closest('.row');\n    if (!row) return;\n    var href = row.dataset.href;\n    if (expandedSet.has(href)){\n      expandedSet.delete(href);\n      if (href === authorPanelTriggerHref) closeAuthorPanel();\n      if (exemptFromExclusion.has(href)){\n        // Collapsing re-exposes it to the tag-exclusion filter, so a story\n        // excluded while expanded now drops out of the list as expected.\n        exemptFromExclusion.delete(href);\n        render();\n        return;\n      }\n    } else {\n      expandedSet.add(href);\n    }\n    renderList(currentFiltered);\n  });\n\n  resultsEl.addEventListener('keydown', function(e){\n    if (e.key !== 'Enter' && e.key !== ' ') return;\n\n    if (viewMode === 'authors'){\n      var storyItem = e.target.closest('.author-story-item:not(.chapter-link)');\n      if (storyItem && e.target === storyItem){\n        e.preventDefault();\n        var storyHref = storyItem.dataset.href;\n        if (authorStoryExpandedSet.has(storyHref)) authorStoryExpandedSet.delete(storyHref);\n        else authorStoryExpandedSet.add(storyHref);\n        renderAuthorList(currentAuthorList);\n        return;\n      }\n      var authorRow = e.target.closest('.author-row');\n      if (!authorRow || e.target !== authorRow) return;\n      e.preventDefault();\n      openAuthorPanel(authorRow.dataset.author, null);\n      return;\n    }\n\n    var row = e.target.closest('.row');\n    if (!row || e.target !== row) return;\n    e.preventDefault();\n    var href = row.dataset.href;\n    if (expandedSet.has(href)){\n      expandedSet.delete(href);\n      if (href === authorPanelTriggerHref) closeAuthorPanel();\n    } else {\n      expandedSet.add(href);\n    }\n    renderList(currentFiltered);\n  });\n\n  function escapeHtml(str){\n    var d = document.createElement('div');\n    d.textContent = str;\n    // innerHTML leaves \" alone, which truncates attribute values such as\n    // data-author=\"BZ\"2\"\" - escape it so names containing quotes survive.\n    return d.innerHTML.replace(/\"/g, '&quot;');\n  }\n\n  function render(){\n    shown = pageSize;\n    updateScopeToggle();\n    updateSavedToggleLabel();\n    if (viewMode === 'authors'){\n      var pool = applyFilters();\n      var authorQuery = searchInput.value.trim().toLowerCase();\n      currentAuthorList = sortAuthorList(buildAuthorList(pool).filter(function(entry){\n        return authorEntryMatches(entry.name, authorQuery);\n      }));\n      renderAuthorList(currentAuthorList);\n    } else {\n      currentFiltered = filterStories();\n      renderList(currentFiltered);\n    }\n    var active = activeTags();\n    var excluded = excludedTags();\n    var rangesActive = wordFilter.active || addedFilter.active || updatedFilter.active;\n    clearBtn.hidden = active.length === 0 && excluded.length === 0 && !searchInput.value.trim() && !rangesActive;\n  }\n\n  var debounceTimer;\n  searchInput.addEventListener('input', function(){\n    clearTimeout(debounceTimer);\n    debounceTimer = setTimeout(render, 120);\n  });\n\n  clearBtn.addEventListener('click', function(){\n    searchInput.value = '';\n    tagCodes.forEach(function(c){\n      chips[c].dataset.state = 'none';\n      chips[c].classList.remove('active', 'excluded');\n    });\n    exemptFromExclusion.clear();\n    updateGroupBadges();\n    wordsSlider.reset(); wordFilter = {lo: wMin, hi: wMax, active: false};\n    addedSlider.reset(); addedFilter = {lo: aMin, hi: aMax, active: false};\n    updatedSlider.reset(); updatedFilter = {lo: uMin, hi: uMax, active: false};\n    render();\n  });\n\n  // ---- Hooks for the userscript host page ----\n  var soloMode = false;\n  function setSolo(on){ soloMode = on; document.documentElement.classList.toggle('solo', on); }\n  window.addEventListener('message', function(e){\n    var d = e.data;\n    if (!d || !d.mco) return;\n    if (d.mco === 'browse'){ setSolo(false); closeAuthorPanel(); }\n    else if (d.mco === 'author'){\n      var want = String(d.name || '').trim().toLowerCase(), found = null;\n      stories.forEach(function(st){\n        authorsOf(st).forEach(function(a){ if (!found && a.toLowerCase() === want) found = a; });\n      });\n      if (!found){ window.parent.postMessage({mco:'author-missing'}, '*'); return; }\n      setSolo(true);\n      openAuthorPanel(found, null);\n      window.parent.postMessage({mco:'author-open'}, '*');\n    }\n  });\n\n  render();\n  } // end init()\n})();\n</script>\n\n<script>\n(function(){\n  function closeOverlay(){ window.parent.postMessage({mco:'close'}, '*'); }\n  var link = document.getElementById('mco-close-link');\n  if (link) link.addEventListener('click', function(e){ e.preventDefault(); closeOverlay(); });\n  // Capture phase so we see Escape before the author panel's own handler closes it.\n  document.addEventListener('keydown', function(e){\n    if (e.key !== 'Escape') return;\n    if (document.body.classList.contains('author-panel-open')) return; // let the panel close first\n    closeOverlay();\n  }, true);\n})();\n</script>\n</body>\n</html>";

  // ---- Data loading -------------------------------------------------------
  function fetchData() {
    return new Promise(function (resolve, reject) {
      GM_xmlhttpRequest({
        method: 'GET',
        url: DATA_URL,
        timeout: 30000,
        onload: function (r) {
          if (r.status < 200 || r.status >= 300) return reject(new Error('HTTP ' + r.status));
          try { resolve(JSON.parse(r.responseText)); } catch (e) { reject(new Error('Bad JSON')); }
        },
        onerror: function () { reject(new Error('Network error')); },
        ontimeout: function () { reject(new Error('Timed out')); }
      });
    });
  }

  function getData(force) {
    var cached = null;
    try { cached = GM_getValue(CACHE_KEY, null); } catch (e) {}
    if (!force && cached && cached.data && Date.now() - cached.t < CACHE_TTL_MS) {
      return Promise.resolve({ data: cached.data });
    }
    return fetchData().then(function (data) {
      try { GM_setValue(CACHE_KEY, { t: Date.now(), data: data }); } catch (e) {}
      return { data: data };
    }).catch(function (err) {
      // Fall back to stale cache rather than showing nothing.
      if (cached && cached.data) return { data: cached.data };
      return { error: err.message };
    });
  }


  // ---- Themes -------------------------------------------------------------
  // Every palette fills the same CSS variables. "default" injects nothing at all,
  // so the site looks exactly as it normally does.
  var THEMES = {
    dark:      { label: 'Dark',              scheme: 'dark',  ink: '#15120e', ink2: '#1d1912', line: '#3a3327', text: '#ede3cf', dim: '#c9bfa8', brass: '#a8823e', bright: '#d9b46a', glow: '#241d13', visited: '#b89a60' },
    midnight:  { label: 'Midnight',          scheme: 'dark',  ink: '#0e1420', ink2: '#151d2d', line: '#27334b', text: '#dbe4f3', dim: '#9fb0c9', brass: '#4f7fd6', bright: '#8ab4ff', glow: '#16233a', visited: '#8fa6d1' },
    black:     { label: 'Black',             scheme: 'dark',  ink: '#000000', ink2: '#0e0e0e', line: '#2a2a2a', text: '#e8e8e8', dim: '#a8a8a8', brass: '#808080', bright: '#ffffff', glow: '#0b0b0b', visited: '#bdbdbd' },
    sepia:     { label: 'Sepia',             scheme: 'light', ink: '#f4ecd8', ink2: '#ebe0c6', line: '#d3c4a1', text: '#3b2f22', dim: '#6b5a45', brass: '#9a6b24', bright: '#7a4d12', glow: '#faf4e4', visited: '#8f6a3a' },
    paper:     { label: 'Paper',             scheme: 'light', ink: '#fafaf7', ink2: '#f0f0ea', line: '#d9d9d0', text: '#222222', dim: '#555555', brass: '#7a7a7a', bright: '#2a5db0', glow: '#ffffff', visited: '#6a4c93' },
    'default': { label: 'MCStories default', scheme: 'light', ink: '#ffffff', ink2: '#f2f2f2', line: '#cccccc', text: '#222222', dim: '#555555', brass: '#888888', bright: '#0645ad', glow: '#ffffff', visited: '#0645ad' }
  };
  var THEME_ORDER = ['dark', 'midnight', 'black', 'sepia', 'paper', 'default'];
  var THEME_KEY = 'mco.themeName';
  var current = 'dark';
  try {
    var saved = GM_getValue(THEME_KEY, null);
    if (!saved) saved = GM_getValue('mco.theme', 'on') === 'off' ? 'default' : 'dark'; // older versions
    if (THEMES[saved]) current = saved;
  } catch (e) {}
  var onThemeChange = null; // set by the switcher so it can re-colour itself

  function themeVars(t) {
    return ':root{--mco-ink:' + t.ink + ';--mco-ink2:' + t.ink2 + ';--mco-line:' + t.line + ';--mco-text:' + t.text +
      ';--mco-dim:' + t.dim + ';--mco-brass:' + t.brass + ';--mco-bright:' + t.bright + ';--mco-glow:' + t.glow +
      ';--mco-visited:' + t.visited + ';color-scheme:' + t.scheme + '}';
  }

  var THEME_CSS = [
    'html{background:var(--mco-ink)!important}',
    'body{background:radial-gradient(1200px 600px at 15% -10%,var(--mco-glow) 0%,transparent 60%),var(--mco-ink)!important;' +
      "color:var(--mco-text)!important;font-family:'Source Serif 4',Georgia,serif!important;font-size:1.125rem!important;" +
      'line-height:1.7!important;max-width:44rem!important;margin:0 auto!important;padding:2rem 1.25rem 5rem!important;box-sizing:border-box!important}',
    'body *{background-color:transparent!important;background-image:none!important;color:var(--mco-text)!important;border-color:var(--mco-line)!important;box-shadow:none!important}',
    'body a,body a *{color:var(--mco-bright)!important;text-decoration-color:var(--mco-brass)!important}',
    'body a:visited,body a:visited *{color:var(--mco-visited)!important}',
    'body a:hover,body a:focus,body a:hover *{color:var(--mco-text)!important}',
    "body h1,body h2,body h3,body h4,body h5{font-family:'Fraunces',Georgia,serif!important;font-weight:600!important;line-height:1.2!important}",
    'body .byline,body .byline *{color:var(--mco-dim)!important;font-weight:400!important}',
    'body hr{border:0!important;border-top:1px solid var(--mco-line)!important;height:0!important}',
    'body p{margin:0 0 1.1em!important}',
    'body nav,body #blurb{color:var(--mco-dim)!important;font-size:.9rem!important}',
    'body input,body select,body textarea{background-color:var(--mco-ink2)!important;border:1px solid var(--mco-line)!important;border-radius:4px!important;padding:.3em .5em!important}',
    'body table,body td,body th{border:1px solid var(--mco-line)!important}',
    'body ::selection{background:var(--mco-brass)!important;color:var(--mco-ink)!important}'
  ].join('\n');

  // ---- Chapter page: make the author's name in the byline a link ----------
  var openAuthorHook = null; // set once the overlay code is ready

  function enhanceReader() {
    var byline = document.querySelector('article#mcstories > h3.byline');
    if (!byline || !document.getElementById('masthead')) return;
    var spans = byline.querySelectorAll('.docAuthor');
    if (!spans.length) return;

    // Author links the page already carries (hidden by the theme, but still in the DOM).
    var known = {};
    var anchors = document.querySelectorAll('nav.arrows a[href*="/Authors/"], nav a[href*="/Authors/"]');
    Array.prototype.forEach.call(anchors, function (a) {
      var name = (a.textContent || '').replace(/^\s*Authors?:\s*/i, '').trim().toLowerCase();
      if (name && !known[name]) known[name] = a.href;
    });
    var rel = document.querySelectorAll('link[rel~="author"][href]');

    Array.prototype.forEach.call(spans, function (span) {
      if (span.querySelector('a')) return; // already a link
      var name = (span.textContent || '').trim();
      if (!name) return;
      var href = known[name.toLowerCase()];
      if (!href && rel.length === 1 && spans.length === 1) href = rel[0].href;
      if (!href) href = location.origin + '/Authors/' + encodeURIComponent(name.replace(/\s+/g, '-')) + '.html';
      var link = document.createElement('a');
      link.href = href;
      link.title = 'More stories by ' + name;
      while (span.firstChild) link.appendChild(span.firstChild);
      span.appendChild(link);
      // Plain click opens the author sidebar; middle/ctrl/shift-click still use the real link.
      link.addEventListener('click', function (e) {
        if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
        if (!openAuthorHook || current === 'default') return;
        e.preventDefault();
        openAuthorHook(name, href);
      });
    });
  }

  // ---- Reader layout (chapter pages only) ---------------------------------
  // Scoped with :has() to pages shaped like a chapter: an #masthead heading and
  // an #mcstories article with a byline. Every other page keeps the plain theme.
  var READER = 'body:has(> h1#masthead):has(> article#mcstories > h3.byline)';
  var MONO = "'IBM Plex Mono',ui-monospace,Menlo,Consolas,monospace";
  var SERIF = "'Source Serif 4',Georgia,serif";
  var DISPLAY = "'Fraunces',Georgia,serif";
  var READER_RULES = [
    // Page: one centered column, content laid out as wrapping rows.
    ['&', 'display:flex!important;flex-wrap:wrap!important;align-items:center!important;column-gap:.6rem!important;row-gap:.5rem!important;' +
          'max-width:42rem!important;padding:1.5rem 1.25rem 4rem!important'],

    // The archive title link is hidden.
    ['& > h1#masthead', 'display:none!important'],

    // The site nav, the "Story:" link and the "Author:" link are hidden (the author's
    // name in the byline links to their page instead). Any other link inside
    // nav.arrows, such as previous/next chapter, is deliberately left alone.
    ['& > nav.site, & > nav.story', 'display:none!important'],
    ['& > nav.arrows a[href*="/Authors/"]', 'display:none!important'],
    ['& > nav.arrows:not(:has(a:not([href*="/Authors/"])))', 'display:none!important'],
    ['& > nav.arrows', 'flex:0 0 100%!important;margin:0!important;padding:0!important;text-align:left!important'],

    // Article: a column whose children are re-ordered visually (title first).
    ['& > article#mcstories', 'flex:0 0 100%!important;display:flex!important;flex-direction:column!important;width:auto!important;max-width:none!important;' +
          'float:none!important;margin:.75rem 0 1.75rem!important;padding:0!important;border:0!important'],
    ['& > article#mcstories > *', 'order:5'],
    ['& > article#mcstories > h3.title', 'order:1;margin:0 0 .5rem!important;text-align:left!important;font:600 clamp(2rem,6vw,2.9rem)/1.08 ' + DISPLAY + '!important;letter-spacing:-.015em!important'],
    ['& > article#mcstories > h3.byline', 'order:2;margin:0 0 1.1rem!important;text-align:left!important;font:400 1.05rem/1.4 ' + SERIF + '!important;color:var(--mco-dim)!important'],
    ['& > article#mcstories > h3.byline .docAuthor', 'color:var(--mco-bright)!important;font-style:italic!important'],
    ['& > article#mcstories > h3.byline .docAuthor a, & > article#mcstories > h3.byline .docAuthor a:visited', 'color:var(--mco-bright)!important;text-decoration:underline transparent!important;text-underline-offset:.2em!important;transition:text-decoration-color .15s ease'],
    ['& > article#mcstories > h3.byline .docAuthor a:hover, & > article#mcstories > h3.byline .docAuthor a:focus-visible', 'text-decoration-color:var(--mco-bright)!important'],
    // The archive's age notice: kept visible, shown as a small note under the byline.
    ['& > article#mcstories > header', 'order:3;margin:0 0 .5rem!important;padding:0!important;align-self:flex-start!important'],
    ['& > article#mcstories > header section.disclaimer', 'border:1px solid var(--mco-line)!important;border-radius:8px!important;padding:.55rem .85rem!important'],
    ['& > article#mcstories > header section.disclaimer p', 'margin:0!important;font-size:.8rem!important;line-height:1.5!important;color:var(--mco-dim)!important'],
    ['& > article#mcstories > header + .milestone', 'display:none!important'],
    ['& > article#mcstories > h3.chapter', 'order:4;margin:1.25rem 0 1.4rem!important;padding-top:1.25rem!important;border-top:1px solid var(--mco-line)!important;text-align:left!important;' +
          'font:500 .72rem/1.4 ' + MONO + '!important;letter-spacing:.2em!important;text-transform:uppercase!important;color:var(--mco-brass)!important'],

    // The story text.
    ['& > article#mcstories > section p', 'font-size:1.14rem!important;line-height:1.78!important;margin:0 0 1.2em!important;text-align:left!important;text-indent:0!important;text-wrap:pretty'],

    // End marker and the author's afterword as a quiet card.
    ['& > article#mcstories > .milestone', 'order:6;display:block!important;text-align:center!important;margin:2.25rem 0!important;font-size:1rem!important;letter-spacing:.6em!important;color:var(--mco-brass)!important'],
    ['& > article#mcstories > footer', 'order:7;margin:0!important;padding:0!important;border:0!important'],
    ['& > article#mcstories > footer section.afterword', 'background-color:var(--mco-ink2)!important;border:1px solid var(--mco-line)!important;border-radius:10px!important;padding:1.1rem 1.3rem .3rem!important'],
    ['& > article#mcstories > footer section.afterword p', 'font-size:.95rem!important;line-height:1.65!important;margin:0 0 .9em!important;color:var(--mco-dim)!important'],

    // Bottom of the page: same pills, then a muted site nav and hosting credit.
    ['& > nav#blurb', 'flex:0 0 100%!important;text-align:center!important;margin:.25rem 0 0!important;padding:0!important;font:400 .72rem/1.5 ' + MONO + '!important;color:var(--mco-dim)!important;opacity:.7'],
    ['& > nav#blurb a, & > nav#blurb a:visited', 'color:var(--mco-dim)!important;text-decoration-color:var(--mco-line)!important']
  ];
  var READER_CSS = READER_RULES.map(function (r) {
    return r[0].split(',').map(function (s) { return s.trim().replace(/^&/, READER); }).join(',') + '{' + r[1] + '}';
  }).join('\n');

  function removeTheme() {
    ['mco-theme', 'mco-fonts', 'mco-fonts-pre'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el && el.parentNode) el.parentNode.removeChild(el);
    });
  }

  function installTheme() {
    if (current === 'default' || document.getElementById('mco-theme')) return;
    var root = document.documentElement;
    if (!root) {
      // Very early in page load the <html> element may not exist yet; wait for it.
      var mo = new MutationObserver(function () {
        if (document.documentElement) { mo.disconnect(); installTheme(); }
      });
      mo.observe(document, { childList: true });
      return;
    }
    var pre = document.createElement('link');
    pre.id = 'mco-fonts-pre'; pre.rel = 'preconnect'; pre.href = 'https://fonts.googleapis.com';
    var fonts = document.createElement('link');
    fonts.id = 'mco-fonts'; fonts.rel = 'stylesheet';
    fonts.href = 'https://fonts.googleapis.com/css2?family=Fraunces:wght@600&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&family=IBM+Plex+Mono:wght@400;500&display=swap';
    var st = document.createElement('style');
    st.id = 'mco-theme';
    st.textContent = themeVars(THEMES[current]) + '\n' + THEME_CSS + '\n' + READER_CSS;
    root.appendChild(pre); root.appendChild(fonts); root.appendChild(st);
  }

  // Switch theme live (no reload) and remember the choice.
  function applyTheme(name) {
    if (!THEMES[name]) return;
    current = name;
    try { GM_setValue(THEME_KEY, name); } catch (e) {}
    removeTheme();
    installTheme();
    if (onThemeChange) onThemeChange();
  }

  installTheme();

  // ---- Overlay ------------------------------------------------------------
  function init() {
  var frame = null;
  var prevOverflow = '';

  function safeJson(obj) {
    return JSON.stringify(obj)
      .replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  }

  function buildFrame(payload) {
    var f = document.createElement('iframe');
    f.id = 'mco-overlay';
    f.title = 'MCStories archive browser';
    f.style.cssText = 'position:fixed!important;inset:0!important;width:100vw!important;height:100vh!important;border:0!important;' +
      'z-index:2147483647!important;background:#15120e!important;display:none;';
    var tag = '<script type="application/json" id="mco-data">' + safeJson(payload) + '</scr' + 'ipt>';
    f.srcdoc = APP_HTML.replace('<!--MCO_DATA-->', function () { return tag; });
    document.body.appendChild(f);
    return f;
  }

  var building = null, pendingHref = null, authorTimer = null;

  function setBackground(solo) {
    frame.style.setProperty('background', solo ? 'transparent' : '#15120e', 'important');
  }
  function tell(msg) { try { frame.contentWindow.postMessage(msg, '*'); } catch (e) {} }

  function show() {
    frame.style.display = 'block';
    prevOverflow = document.documentElement.style.overflow;
    document.documentElement.style.overflow = 'hidden';
    launcher.style.display = 'none';
    try { frame.contentWindow.focus(); } catch (e) {}
  }

  function hide() {
    if (!frame) return;
    frame.style.display = 'none';
    document.documentElement.style.overflow = prevOverflow;
    launcher.style.display = '';
  }

  // Builds the overlay once (data first). A frame is built even if the data failed,
  // so the browse view can show its own error message.
  function ensureFrame() {
    if (building) return building;
    if (frame) return Promise.resolve({});
    building = getData(false).then(function (payload) {
      return new Promise(function (resolve) {
        frame = buildFrame(payload);
        frame.addEventListener('load', function () { resolve({ error: payload.error }); }, { once: true });
      });
    }).then(function (r) { building = null; return r; });
    return building;
  }

  function open() {
    launcher.textContent = 'Loading…';
    ensureFrame().then(function () {
      setBackground(false);
      tell({ mco: 'browse' });
      show();
    }).finally(function () { launcher.textContent = 'Browse stories'; });
  }

  // Opened from a story page: just the author sidebar over the story. If the author
  // isn't in the data (or it couldn't load) fall back to the normal author page.
  function openAuthor(name, href) {
    pendingHref = href;
    ensureFrame().then(function (r) {
      if (r.error) { location.href = href; return; }
      setBackground(true);
      clearTimeout(authorTimer);
      authorTimer = setTimeout(function () { location.href = href; }, 2500);
      tell({ mco: 'author', name: name });
    });
  }
  openAuthorHook = openAuthor;

  function refresh() {
    var wasOpen = frame && frame.style.display === 'block';
    if (frame) { frame.remove(); frame = null; }
    launcher.textContent = 'Refreshing…';
    getData(true).then(function (payload) {
      frame = buildFrame(payload);
      frame.addEventListener('load', function () {
        if (wasOpen) show();
        launcher.textContent = 'Browse stories';
      }, { once: true });
    });
  }

  // ---- Launcher button ----------------------------------------------------
  var launcher = document.createElement('button');
  launcher.type = 'button';
  launcher.textContent = 'Browse stories';
  launcher.style.cssText =
    'position:fixed!important;right:18px!important;bottom:18px!important;z-index:2147483646!important;padding:.55em 1.1em!important;' +
    'font:500 13px/1.2 ui-monospace,Menlo,Consolas,monospace!important;letter-spacing:.06em!important;' +
    'color:var(--mco-text,#ede3cf)!important;background:var(--mco-ink2,#1d1912)!important;border:1px solid var(--mco-brass,#a8823e)!important;border-radius:999px!important;' +
    'cursor:pointer!important;box-shadow:0 4px 14px rgba(0,0,0,.35)!important;margin:0!important;max-width:none!important;';
  launcher.addEventListener('mouseenter', function () { launcher.style.setProperty('border-color', 'var(--mco-bright,#d9b46a)', 'important'); });
  launcher.addEventListener('mouseleave', function () { launcher.style.setProperty('border-color', 'var(--mco-brass,#a8823e)', 'important'); });
  launcher.addEventListener('click', open);
  document.body.appendChild(launcher);

  // ---- Theme switcher (top right) -----------------------------------------
  // Lives in a shadow root so neither the site's CSS nor the theme can restyle it.
  var switcherHost = document.createElement('div');
  switcherHost.id = 'mco-switcher';
  switcherHost.style.cssText = 'position:fixed!important;top:14px!important;right:14px!important;z-index:2147483645!important;' +
    'margin:0!important;padding:0!important;background:none!important;border:0!important;width:auto!important;height:auto!important;' +
    'font-size:16px!important;line-height:1!important;max-width:none!important;';
  var sroot = switcherHost.attachShadow({ mode: 'open' });
  sroot.innerHTML =
    '<style>' +
    '*{box-sizing:border-box;font-family:ui-monospace,Menlo,Consolas,monospace}' +
    '.btn{width:34px;height:34px;border-radius:50%;border:1px solid var(--line);background:var(--bg);color:var(--fg);cursor:pointer;' +
      'display:flex;align-items:center;justify-content:center;padding:0;box-shadow:0 4px 14px rgba(0,0,0,.25)}' +
    '.btn:hover,.btn:focus-visible{border-color:var(--accent);outline:none}' +
    '.menu{position:absolute;top:42px;right:0;min-width:236px;background:var(--bg);color:var(--fg);border:1px solid var(--line);' +
      'border-radius:12px;padding:6px;box-shadow:0 12px 32px rgba(0,0,0,.35);display:none}' +
    '.menu.open{display:block}' +
    '.title{font-size:.64rem;letter-spacing:.18em;text-transform:uppercase;color:var(--accent);padding:.45rem .6rem .35rem}' +
    '.item{display:flex;align-items:center;gap:.65rem;width:100%;padding:.5rem .6rem;border:0;border-radius:8px;background:none;' +
      'color:var(--fg);font-size:.78rem;letter-spacing:.02em;cursor:pointer;text-align:left}' +
    '.item:hover,.item:focus-visible{background:var(--hover);outline:none}' +
    '.sw{width:22px;height:22px;border-radius:50%;border:1px solid var(--line);position:relative;flex:none}' +
    '.sw::after{content:"";position:absolute;right:3px;bottom:3px;width:9px;height:9px;border-radius:50%;background:var(--dot)}' +
    '.check{margin-left:auto;opacity:0;color:var(--accent)}' +
    '.item[aria-checked="true"] .check{opacity:1}' +
    '.item span{white-space:nowrap}' +
    '.sep{height:1px;background:var(--line);margin:4px 2px}' +
    '</style>' +
    '<button type="button" class="btn" aria-haspopup="menu" aria-expanded="false" aria-label="Change theme" title="Change theme">' +
      '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">' +
      '<circle cx="12" cy="12" r="8.5"/><path d="M12 3.5a8.5 8.5 0 0 1 0 17z" fill="currentColor"/></svg></button>' +
    '<div class="menu" role="menu" aria-label="Theme"><div class="title">Theme</div></div>';
  var sBtn = sroot.querySelector('.btn');
  var sMenu = sroot.querySelector('.menu');

  THEME_ORDER.forEach(function (key) {
    var t = THEMES[key];
    if (key === 'default') { var sep = document.createElement('div'); sep.className = 'sep'; sMenu.appendChild(sep); }
    var item = document.createElement('button');
    item.type = 'button'; item.className = 'item'; item.setAttribute('role', 'menuitemradio');
    item.dataset.theme = key;
    item.innerHTML = '<span class="sw" style="background:' + t.ink + ';--dot:' + t.bright + '"></span>' +
      '<span>' + t.label + (key === 'dark' ? ' (default)' : '') + '</span><span class="check" aria-hidden="true">&#10003;</span>';
    sMenu.appendChild(item);
  });

  function paintSwitcher() {
    // Chrome follows the active theme; on the unstyled site it stays a neutral dark pill.
    var t = current === 'default'
      ? { ink2: '#1d1912', text: '#ede3cf', line: '#3a3327', bright: '#d9b46a' }
      : THEMES[current];
    switcherHost.style.setProperty('--bg', t.ink2);
    switcherHost.style.setProperty('--fg', t.text);
    switcherHost.style.setProperty('--line', t.line);
    switcherHost.style.setProperty('--accent', t.bright);
    switcherHost.style.setProperty('--hover', t.line);
    Array.prototype.forEach.call(sMenu.querySelectorAll('.item'), function (it) {
      it.setAttribute('aria-checked', it.dataset.theme === current ? 'true' : 'false');
    });
  }
  onThemeChange = paintSwitcher;
  paintSwitcher();

  function setMenu(open) {
    sMenu.classList.toggle('open', open);
    sBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  sBtn.addEventListener('click', function () { setMenu(!sMenu.classList.contains('open')); });
  sMenu.addEventListener('click', function (e) {
    var item = e.target.closest ? e.target.closest('.item') : null;
    if (!item) return;
    applyTheme(item.dataset.theme);
    setMenu(false);
    sBtn.focus();
  });
  document.addEventListener('click', function (e) {
    if (sMenu.classList.contains('open') && e.composedPath().indexOf(switcherHost) === -1) setMenu(false);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && sMenu.classList.contains('open')) { setMenu(false); sBtn.focus(); }
  });
  document.body.appendChild(switcherHost);

  window.addEventListener('message', function (e) {
    var d = e.data;
    if (!d || !d.mco) return;
    if (d.mco === 'close') hide();
    else if (d.mco === 'author-open') { clearTimeout(authorTimer); show(); }
    else if (d.mco === 'author-missing') { clearTimeout(authorTimer); if (pendingHref) location.href = pendingHref; }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && frame && frame.style.display === 'block') hide();
  });

  if (typeof GM_registerMenuCommand === 'function') {
    GM_registerMenuCommand('Open archive browser', open);
    GM_registerMenuCommand('Refresh story data now', refresh);
    GM_registerMenuCommand('Change theme…', function () { setMenu(!sMenu.classList.contains('open')); });
  }
  }

  function onReady() { try { enhanceReader(); } catch (e) {} init(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', onReady);
  else onReady();
})();
